// Public profile context for Speedrun companies, snapshot October 2026.
// Each entry links back to its public company source in the main roster.
window.SPEEDRUN_CONTEXT = {
  "SR001:Canto Reality": {"founded":2023,"overview":"Canto Reality builds social experiences powered by AI, targeting consumer audiences. The company operates as an exploratory deployment lab, testing and shipping interactive social products. Its work sits at the intersection of AI research and consumer application, replacing static or conventional social formats with AI-driven interactions."},
  "SR001:Elsewhere": {"founded":2024,"overview":"Elsewhere builds multiplayer video games that use generative AI to make each session distinct, targeting players who want shared, replayable adventures with friends. The studio treats AI as a core production tool rather than a gimmick, replacing the fixed, hand-scripted experiences that traditional game development delivers."},
  "SR001:Ex-Human": {"founded":2021,"overview":"Ex-Human builds an empathetic AI platform that lets businesses create AI characters capable of text, image, and video interactions. The platform is trained on real conversational data to produce emotionally responsive, personalized exchanges. It serves consumer and B2B clients in media, entertainment, and the creator economy, replacing scripted chatbots and static virtual characters with companions that adapt to individual users."},
  "SR001:GGFolks": {"founded":2019,"overview":"GGFolks builds and operates cross-platform MMOs, targeting casual and community-oriented gamers on Steam, iOS, and Android. Its flagship title, Puzzle Wizards, is a cozy co-op MMO in early access, while the team also helps run legacy titles Puzzle Pirates and Spiral Knights, which retain active player communities. The studio replaces third-party publishing by owning the full development and operations stack across its game portfolio."},
  "SR001:Househunt": {"founded":2023,"overview":"Househunt turns real residential listings into a mobile game where players guess house prices, then buy, fix, and flip properties to build a virtual real estate portfolio. It targets casual and real-estate-curious players who want the strategy of property investing without real capital at stake, replacing board games like Monopoly with actual market data and real home listings."},
  "SR001:Incite Interactive": {"founded":2023,"overview":"Incite Interactive builds AuraVale, an agentic life simulation game where players shape open-ended narratives through natural language rather than following scripted storylines. The studio also develops the underlying agentic game engine, which lets anyone create AI-driven characters and scenarios and share them on the platform. The product targets players who want authored, personal stories and replaces the fixed narrative structures of traditional life simulation games."},
  "SR001:Level Headed Games": {"founded":2023,"overview":"Level Headed Games builds original multiplayer games targeting Gen Z and cross-generational players. Its debut title, Whimpact!, combines arena party-game mechanics in the vein of Fall Guys or Mario Kart with a creature-collection system, where players level up companions called Whims to gain in-game powers, adding long-term progression to short-session play. The studio draws on team experience across billion-dollar franchises to produce commercial-scale titles without the budgets of major publishers."},
  "SR001:Matchday": {"founded":2022,"overview":"Matchday builds casual mobile soccer games for the global soccer fan base, starting with Matchday Champions, a collectible card squad-builder using officially licensed players from FIFPRO's roster of professional athletes. The product targets the large casual end of the gaming market that major sports titles have historically underserved, replacing unlicensed or generic soccer game experiences with real player IP."},
  "SR001:Neon": {"founded":2022,"overview":"Neon builds white-label e-commerce and payments infrastructure for mobile and PC game studios that want to sell directly to players outside the app stores. Studios use Neon's platform to launch web shops, handle global checkout, and manage subscriptions and virtual-goods SKUs, replacing a patchwork of payment processors and custom storefront builds. The product lets game teams own the customer relationship and capture margin that would otherwise go to platform fees."},
  "SR001:Original Games": {"founded":2019,"overview":"Original Games develops casual mobile games built for broad, mainstream audiences. Its current title, Merge Inn, targets players who want relaxing, session-friendly gameplay, replacing the low-engagement, low-retention experiences that dominate the casual market. The team draws on veterans from Rovio, Wooga, EA, and Easybrain to compete for the next breakout casual hit."},
  "SR001:Rascal Games": {"founded":2023,"overview":"Rascal Games builds a social gaming platform where players form lasting friend groups, create shared identities, and go on adventures together. It targets gamers who want an ongoing digital home with their friends, replacing the scattered, transient social experience of hopping between disconnected games and chat tools."},
  "SR001:Ray Browser": {"founded":2022,"overview":"Ray Browser builds a desktop web browser for everyday consumers that replaces passive, generic browsing with a personalized, agent-driven experience. A built-in AI agent searches the web and acts on open tabs on the user's behalf, a daily Discover feed surfaces content based on the user's own reading and activity, and Ray Studio lets users build tools, dashboards, and apps from their data using plain-language descriptions, no code required."},
  "SR001:Rosebud AI": {"founded":2020,"overview":"Rosebud AI builds a browser-based game creation platform that lets non-technical creators build and publish games through natural-language prompts, replacing the need to write code or use traditional game engines. Creators describe a game concept and the platform generates a playable result, covering 2D, 3D, RPG, visual novel, and other formats. The product targets hobbyists, educators, and creators who want to make games without engineering skills."},
  "SR001:Runware": {"founded":2023,"overview":"Runware builds a unified API for AI-generated images, audio, and video, running on proprietary renewable-energy hardware. It targets developers and product teams who need generative media at scale without managing infrastructure or machine-learning models. The API replaces in-house GPU provisioning and model deployment, delivering sub-second generation at a fraction of typical cloud inference costs."},
  "SR001:Sloyd": {"founded":2023,"overview":"Sloyd builds an AI-powered 3D model creation platform for game developers, animators, AR/VR creators, and 3D printing enthusiasts. Users generate production-ready 3D assets from text prompts or images and refine them through templates, sliders, and toggles, replacing manual modeling work in tools like Blender or Maya. The platform supports in-game user-generated content creation, extending its reach beyond solo creators to game studios enabling player-built worlds."},
  "SR001:SuperGaming": {"founded":2019,"overview":"SuperGaming builds and operates real-time multiplayer mobile games targeting the next billion players across emerging markets. The studio develops original titles, including the Indo-futuristic battle royale Indus for India and Prime Rush for Brazil and MENA, replacing the gap left by Western-designed games that ignore regional culture and infrastructure. It also co-develops and operates multiplayer games for third-party publishers, handling full-cycle development, live operations, localization, and user acquisition."},
  "SR001:Talofa Games": {"founded":2019,"overview":"Talofa Games builds a platform for creators to develop and publish fitness games targeting Gen Z players. Its flagship title, Run Legends, turns physical movement into mobile gameplay, replacing passive screen time with activity-driven sessions. The company also has Monster Walk in closed beta, expanding its roster of motion-based games."},
  "SR001:The Possible Company": {"founded":2023,"overview":"The Possible Company builds an AI-powered moviemaking tool that turns written content into short animated films. Writers, bloggers, and newsletter authors use it to convert existing text into video with generated images, voiceover, and sound, replacing manual video production. The product meets storytellers at the writing stage and handles the rest of the media assembly automatically."},
  "SR001:Torbie": {"founded":2022,"overview":"Torbie builds cooperative, exploration-driven games for players who want shared discovery alongside systemic depth. Its debut title, Everbloom, is a farming and homestead game where players tend animals with heritable traits, build and customize a farm, and explore a handcrafted open world full of hidden stories. The studio targets the cozy-game and co-op audience, replacing more passive solo play with systems that reward curiosity and connection."},
  "SR001:Trass Games": {"founded":2021,"overview":"Trass Games builds Yeeps, a free-to-play social VR game on Meta Quest where players create and share user-generated content in the style of sandbox titles like Minecraft and Roblox. The studio is expanding Yeeps from a hide-and-seek game into a full UGC platform, replacing the PC and mobile sandbox experience with a VR-native equivalent. The work it displaces is the flat-screen, controller-based creative multiplayer session."},
  "SR001:Unleashed Games": {"founded":2022,"overview":"Unleashed Games builds Haven, a cross-platform cooperative RPG for families and friends, targeting an underserved audience of female gamers and gamer parents. Players explore a shared fantasy world together across PC, Mac, console, and mobile, replacing solitary or competitive play with collaborative adventure. The team behind titles such as World of Warcraft, Medal of Honor, and Monopoly Go! is designing the experience around social connection rather than competition."},
  "SR001:Uthana": {"founded":2023,"overview":"Uthana builds generative AI models for 3D human motion, serving game studios, simulation teams, and robotics developers. Its platform converts text or video into editable, production-ready character animation and transfers that motion across character skeletons or humanoid robots. It replaces manual animation workflows, including rigging, retargeting, and motion blending, that traditionally take days or weeks of artist time."},
  "SR001:Voidpet": {"founded":2021,"overview":"Voidpet builds a mobile RPG around collectible emotion-based creatures called Voidpets, targeting players who engage with character-driven games. The product spans a game, an anime, and an illustrated creature index, replacing passive entertainment with an expanding interactive universe players collect and explore."},
  "SR001:Windwalk": {"founded":2018,"overview":"Windwalk builds an enterprise community platform for large gaming and entertainment fandoms, giving marketing teams a single place to unify fan audiences from Discord, web hubs, email, and connected platforms into one customer profile. It replaces the manual work of stitching together data from separate community tools, letting teams run gamified campaigns, quests, and rewards programs from one system. The result is structured, first-party social data that informs acquisition and retention campaigns."},
  "SR001:Zibra AI": {"founded":2021,"overview":"Zibra AI builds GPU-native compression infrastructure for large-scale 3D and volumetric data, targeting teams training spatial AI models in robotics, autonomous systems, digital twins, and simulation-heavy domains. Its PyTorch-integrated pipeline compresses 3D datasets and decompresses them in real time at the GPU, raising utilization and accelerating model convergence without changes to existing training workflows. On the content-creation side, the same compression technology powers real-time volumetric rendering tools for VFX, virtual production, and game development inside Unreal Engine and Unity, replacing offline render pipelines."},
  "SR002:Aghanim": {"founded":2023,"overview":"Aghanim builds a direct-to-consumer platform for mobile game studios, letting them sell to players on the web instead of routing all commerce through app stores. Its core product is a browser-based game hub, generated automatically using generative AI, that bundles storefront, live-ops, and community features into a single portal. Studios use it to run targeted offers, creator programs, and payment flows, replacing the patchwork of in-app purchase limits and third-party tools those jobs previously required."},
  "SR002:Braid": {"founded":2022,"overview":"Braid builds an AI-powered employee engagement platform that runs inside Slack, automating the games, polls, events, and reminders that HR and team managers otherwise schedule and run by hand. It targets remote and hybrid teams, replacing the manual coordination work behind culture programs with AI-generated scheduling, personalized activity recommendations, and automated participation nudges. The product also surfaces engagement insights through AI-generated reports, removing the need for manual tracking."},
  "SR002:Clementine": {"founded":2024,"overview":"Clementine builds games that rewrite their own rules and code in real time based on player input in natural language, making the act of modding the game itself the core mechanic. Its first title is a monster trainer. The underlying system generates functional code on the fly, replacing the static, designer-authored rules that conventional games ship with."},
  "SR002:Crater Studios": {"founded":2024,"overview":"Crater Studios builds PC and console games using a production model that combines AAA-quality depth with indie-scale speed and cost. The studio uses AI-driven workflows and modular development frameworks to prototype, test, and ship titles faster than traditional studios. Its portfolio includes the launched title Dwarven Realms and games in progress across the extractor shooter and collectible card game genres."},
  "SR002:Dare Drop": {"founded":2019,"overview":"Dare Drop builds a gaming influencer marketing platform for game publishers and studios. It connects brands with Twitch, YouTube, and TikTok creators through structured, reward-driven challenges called Dares, replacing the manual, agency-run outreach that publishers typically use to promote titles. Publishers set goals and rewards; creators complete in-game or on-stream challenges for their audiences, driving sustained content and community engagement."},
  "SR002:Dream Voyage": {"founded":2024,"overview":"Dream Voyage builds AI-powered consumer products across spiritual wellness, social payments, and social gaming. Its portfolio includes SINE Daily Manifest, an AI spiritual health app; Vdrop, which lets users send money to others with a single tweet; and RPS, a Solana-based social game. The studio targets mainstream consumers and replaces conventional app-store categories with social-native, shareable experiences designed to spread organically on short-form video platforms."},
  "SR002:Drill Creative": {"founded":2023,"overview":"Drill Creative builds gaming experiences for core gaming audiences using agentic AI, replacing traditional manual game design and content-creation workflows. The company is in stealth and has not yet disclosed product details publicly."},
  "SR002:First Day Entertainment": {"founded":2024,"overview":"First Day Entertainment builds AI-powered video games for solo players who want social and cooperative gameplay without the friction of online multiplayer. Its two released titles are Heroes of Magic and Cards, a poker-based deckbuilding roguelike, and Mana Land, a single-player RPG where AI companions replace human teammates for group-style questing and conversation. The games target players who seek the depth and camaraderie of multiplayer experiences but prefer to play on their own schedule and outside competitive online environments."},
  "SR002:Gamebeast": {"founded":2023,"overview":"Gamebeast builds an AI-native platform that gives game studios a single intelligence layer across analytics, live operations, community insights, and attribution. Studios use it to understand player behavior and act on it across the full player lifecycle, replacing a fragmented stack of separate analytics tools, manual LiveOps workflows, and ad-hoc data queries. An autonomous AI agent runs continuously, surfacing insights and executing decisions without requiring a data team or SQL expertise."},
  "SR002:Gridsnap": {"founded":2024,"overview":"Gridsnap builds interactive experiences inside the Fortnite ecosystem using Unreal Editor for Fortnite, developing its own original IP and co-creating branded spaces for influencers and their communities on the platform. It also takes equity stakes in games made by emerging developers in exchange for direct development support, replacing the gap between solo creator ambition and production capacity."},
  "SR002:Hedra": {"founded":2023,"overview":"Hedra builds visual inference models and a production platform that lets creative and enterprise teams generate images, video, and audio from a single environment. Its proprietary Character-3 is a multimodal video model; the platform also routes work across leading third-party foundation models through one agent-driven interface. Prosumers use it for social content and branded marketing, replacing fragmented tool stacks and manual production workflows."},
  "SR002:k-ID": {"founded":2023,"overview":"k-ID builds compliance infrastructure for platforms with youth audiences, including gaming, social media, and consumer AI. Its product suite covers age classification, high-assurance age verification, reusable age credentials, market-specific compliance logic, and regulatory intelligence, replacing the manual work of tracking and implementing child-safety rules across more than 200 jurisdictions. Operators use k-ID to stay compliant with laws such as COPPA, the UK Online Safety Act, and Brazil's ECA Digital without building that regulatory and technical layer themselves."},
  "SR002:Legion": {"founded":2023,"overview":"Legion Studios builds Covenant, a first-person action game set in a dark fantasy world with mythical themes. The studio targets players who want narrative-driven, combat-focused single-player experiences in a genre dominated by AAA titles. Legion handles the full creative and development pipeline in-house, from world-building to production."},
  "SR002:Lil Snack": {"founded":2023,"overview":"Lil Snack builds a daily web-based games platform for casual players, publishing a fresh set of bite-sized games each day tied to pop culture themes. It replaces the scattered, one-off casual game experience with a structured daily ritual, complete with streaks, leaderboards, and community discussion. The platform also distributes games through media partners such as Amazon Prime, Peacock, BuzzFeed, and Imgur, reaching audiences where they already spend time."},
  "SR002:LIVE AWARE": {"founded":2023,"overview":"LIVE AWARE gives game development teams a single platform to capture, consolidate, and analyze player feedback across playtests, Discord, Twitch, YouTube, and internal sessions. Its AI automatically organizes and tags gameplay footage and community input, then surfaces trending bugs and player pain points linked directly to video clips. The product replaces the manual work of sifting through scattered recordings, comment threads, and bug reports to prioritize fixes."},
  "SR002:Magic Circle Studio": {"founded":2022,"overview":"Magic Circle Studio builds AI-powered multiplayer games designed for close friend groups, playable inside Discord and on the web. Players use built-in AI tools to remix game content around their group's shared humor and inside jokes, replacing generic party games with something tailored to each circle of friends."},
  "SR002:Neon Wild": {"founded":2021,"overview":"Neon Wild builds personalized, interactive story worlds for children, placing each child as the hero of their own narrative. The product targets parents seeking engaging, confidence-building experiences for young kids, replacing generic passive media with stories tailored to the individual child. Neon Wild's initial content is built around the DreamWorks property Gabby's Dollhouse."},
  "SR002:Parhelion Studio Co.": {"founded":2024,"overview":"Parhelion Studio Co. builds anime-style live-service games for gamers, enthusiasts, and hobbyists, developing original IPs with original characters and world-building lore. The studio handles continuous post-launch updates and incorporates direct player feedback into development, replacing the traditional fixed-release model. It also maintains a global artist network capable of producing full anime short-form productions."},
  "SR002:Plutus Labs": {"founded":2023,"overview":"Plutus Labs builds an AI-powered interactive simulation platform where users step inside self-generated story worlds, make choices, and shape outcomes in real time. Players describe a scenario, the platform builds a playable \"World Sim\" around it, and characters within that sim communicate directly with the user. The product replaces passive content consumption with personalized, decision-driven narrative play across genres from dark romance to sci-fi."},
  "SR002:Qloud Games (Loftia)": {"founded":2022,"overview":"Loftia builds a cozy social MMO where players explore floating islands, farm using sustainable techniques, craft, and complete quests alongside friends and NPCs. The game targets players seeking a low-stress, community-driven online world, replacing the grind and combat loops of conventional MMOs with cooperative building, creature adoption, and neighbourhood-sharing. It is in development for PC via Steam Early Access."},
  "SR002:Quago": {"founded":2022,"overview":"Quago analyzes in-game device sensor data and player connectivity to give gaming studios detection and prediction capabilities that standard mobile measurement tools miss. On the fraud side, it identifies cheaters and fake traffic inflating user acquisition campaigns in real time. On the growth side, it predicts churn probability, skill level, and lifetime value from the first session, replacing manual review and guesswork with automated, privacy-safe signals."},
  "SR002:Rivet": {"founded":2023,"overview":"Rivet builds open-source orchestration infrastructure for agentic workloads, serving developers who run AI agents at scale. Its core primitives, Actors, Workflows, Sandboxes, and Dynamic Apps, give each agent a durable process, a stateful execution environment, and a filesystem, replacing ad-hoc server setups and custom session management. Developers can self-host or use Rivet's cloud to deploy agents that persist across restarts and spin up in milliseconds."},
  "SR002:StyleFrame": {"founded":2023,"overview":"StyleFrame builds a professional AI video toolkit for motion designers, animators, and VFX artists. It gives practitioners keyframe-based timeline control, motion referencing, restyle, and ink-and-paint tools, replacing manual in-betweening and iterative prompt-box workflows. Artists direct output using visuals and can revise any element after the fact without restarting a project."},
  "SR002:Tractive": {"founded":2023,"overview":"Tractive builds AI tools that automate the technical preparation steps 3D artists must complete before an asset is usable in a game engine, covering mesh retopology, UV unwrapping, and rigging. The target users are character artists, environment artists, technical directors, and riggers who currently perform these steps by hand. Automating that work cuts the time from sculpt to game-ready asset by a factor of ten."},
  "SR002:videogame.ai": {"founded":2023,"overview":"videogame.ai builds games using a fully autonomous, agent-based production system modeled on a traditional game studio pipeline, with AI agents covering every specialty from coding to asset management. It targets game studios and publishers who need to ship titles and live-ops updates faster and at lower cost than a conventional development team. The product replaces the bulk of manual game development work, delivering a complete game build in three days at the cost of a single full-time employee."},
  "SR003:2weeks": {"founded":2024,"overview":"2weeks builds and modernizes games for players on new platforms, starting with a reforged update to Guild Wars that brings the classic online RPG to controllers and Steam Deck. The studio runs rapid prototype cycles to find games that can grow into durable franchises, using a custom engine and pipeline built in-house. It replaces the slow, resource-heavy development process typical of established studios with a lean, iterative toolkit designed to move from experiment to shippable product in weeks."},
  "SR003:Adzap": {"founded":2024,"overview":"Adzap builds a player acquisition and attribution platform for PC and console games, bringing performance marketing tooling to a segment that has lacked it while mobile advertising matured. It targets game publishers and studios that need to measure and optimize user acquisition outside of mobile storefronts, replacing manual, fragmented tracking with integrated performance data. The platform connects with Unity, Unreal Engine, and custom engines to run attribution natively within PC and console titles."},
  "SR003:AvatarOS": {"founded":2023,"overview":"AvatarOS builds AI-driven digital human avatars for brands and media creators, using proprietary 4D and machine learning technology to replicate a person's motion, mannerisms, and physical nuance. The team previously created Miquela, a virtual influencer with tens of millions of streams and followers. AvatarOS replaces traditional film-grade VFX animation, which can run into the millions of dollars per hour of content, with dynamically generated avatars that require no per-frame animation cost."},
  "SR003:Clouted": {"founded":2024,"overview":"Clouted builds a managed content distribution platform for artists, labels, gaming studios, and consumer brands. Its engine converts raw footage into short-form clips and pushes them through a network of trained creators, replacing traditional performance marketing campaigns. Clients use it to drive streams, ticket sales, and social engagement at scale."},
  "SR003:Communion": {"founded":2023,"overview":"Communion builds Altar, a social deduction battle royale game that blends fashion, gaming, and blockchain elements into an evolving multiplayer experience. The game targets players who want competitive, scenario-driven social gameplay, replacing static game narratives with a continuously shifting set of outcomes and roles. Altar is the studio's first title and the foundation of a broader \"life matrix\" game universe."},
  "SR003:Crema Social": {"founded":2023,"overview":"Crema Social connects people internationally through a combined video call and food delivery experience, letting users share a meal together over live video. The platform targets the international dating and social discovery market, replacing the static swipe-and-message format with a structured, shared mealtime interaction. It positions itself at the intersection of virtual connection and local food delivery."},
  "SR003:Definitely Games": {"founded":2024,"overview":"Definitely Games builds online cooperative games. The studio is run by two engineers with prior game industry exits, combining creative and technical depth to develop and scale multiplayer co-op experiences for players."},
  "SR003:Echo Chunk": {"founded":2024,"overview":"Echo Chunk builds AI-generated strategy games targeting casual and mass-market players who find traditional chess too steep a climb. Its first title, Echo Chess, is a daily chess puzzle where each challenge is generated by AI, giving players a fresh problem every day without the overhead of learning full competitive chess. The company also ships a Playground builder that lets players create and share their own puzzle variations."},
  "SR003:Eclipsa AI": {"founded":2024,"overview":"Eclipsa AI builds a conversational commerce platform for gaming publishers, letting them sell in-game purchases and manage player relationships directly through WhatsApp. It replaces app-store and web checkout flows with chat-native transactions inside a messaging channel players already use. The founding team comes out of Meta, with hands-on experience in messaging infrastructure and commerce."},
  "SR003:Else": {"founded":2024,"overview":"Else builds adjunct preview environments that let anyone on a product team, QA, designers, PMs, and non-engineers, review and edit AI-generated code changes directly inside a live, isolated environment. Instead of opening tickets that cycle back to an engineer over multiple days, reviewers fix bugs, correct visuals, and propose UX forks through an in-browser agent and visual editor. The result collapses a multi-day PR review loop into a single pass."},
  "SR003:Endo Health": {"founded":2024,"overview":"Endo Health builds an AI-native weight loss clinic that replaces fragmented in-person care. Glow, its AI companion, coaches patients through daily voice conversations while an integrated telehealth layer handles prescriptions and physician oversight. The product targets people seeking GLP-1 and weight loss treatment, managing the full care cycle from consultation to medication delivery without a physical clinic."},
  "SR003:Entropia": {"founded":2024,"overview":"Entropia builds an AI-powered platform that converts webcomic episodes into short, animated anime-style videos, targeting Gen Z audiences. The work it replaces is the labor-intensive traditional animation pipeline, where a single second of footage requires multiple hand-drawn panels and many hours of production time. By collapsing that process with generative AI, Entropia creates a new format sitting between static webcomics and full anime series."},
  "SR003:Exia Labs": {"founded":2024,"overview":"Exia Labs builds Blue, a spatial intelligence platform that commands and coordinates mixed teams of autonomous robots and human operators on defense missions. Blue handles command and control, mission planning, and task assignment across air, ground, and other autonomous systems, replacing manual coordination work for intelligence, surveillance, reconnaissance, and targeting operations. The platform serves military customers executing human-machine integrated formations in contested environments."},
  "SR003:Flat2VR Studios": {"founded":2022,"overview":"Flat2VR Studios converts existing flatscreen video games into full VR titles, handling development, funding, publishing, and go-to-market on behalf of IP holders. The studio targets game publishers and rights owners who want a VR version of their title without building that capability in-house. Released ports include Roboquest VR, Trombone Champ Unflattened, and titles across Meta Quest, PlayStation, Steam, and Google Play, with additional adaptations in active development."},
  "SR003:Hatsu Labs": {"founded":2024,"overview":"Hatsu Labs builds AI agent technology for the gaming industry. The company targets game developers and publishers, applying autonomous agents to automate or augment work that has traditionally required significant human effort in game production or operations."},
  "SR003:Human Computer": {"founded":2023,"overview":"Human Computer builds story-driven video games and publishes written and video content about game design. Its debut title, Ballgame, is scheduled for 2027 and available to wishlist on Steam. The studio targets players who want original IP with high production values, replacing the mid-tier gap between indie and AAA releases with a new category its founders call triple-I."},
  "SR003:Keewano": {"founded":2024,"overview":"Keewano builds KeewanoDB, a database designed for AI agents that need to reason over complete, ordered event sequences. Traditional analytics databases store current state and predefined views, forcing teams into weeks-long data reconstruction projects whenever a new question arises. KeewanoDB stores every event contiguously and in order so agents can query the full historical record instantly, without waiting for a new pipeline."},
  "SR003:LFG": {"founded":2024,"overview":"LFG builds and funds games on Roblox, targeting Gen Alpha players. The studio applies a capital-efficient, high-velocity production approach to a platform where most developers have struggled to produce breakout hits. It combines in-house development expertise with funding to back external creators, replacing the slow, undercapitalized model typical of UGC game studios."},
  "SR003:Little Umbrella": {"founded":2023,"overview":"Little Umbrella builds social AI party games that run natively on Discord, replacing static, human-scripted party game formats with AI-driven mechanics that generate dynamic scenarios and personalized gameplay for groups. Its first title, Death by AI, is a multiplayer party game where players compete against AI-generated prompts and judgments. Three additional titles are in development, and the studio also offers Playroom Kit, a platform that lets third-party developers publish Discord-native games using Little Umbrella's infrastructure."},
  "SR003:Manifest": {"founded":2024,"overview":"Manifest builds a mental health and self-care app aimed at Gen Z users who want structured, daily support for emotional wellness. The app delivers personalized challenges, guided meditations, and AI-powered voice support that adapt to each user over time, replacing ad-hoc or passive self-care habits with a gamified, streak-based routine. A virtual companion and crystal reward system reinforce daily engagement and habit formation."},
  "SR003:NoMi": {"founded":2023,"overview":"NoMi delivers therapeutic self-development outcomes through mobile games aimed at Gen-Z users. Players work through relatable scenarios that challenge negative thinking patterns and build confidence, replacing traditional therapy and formal self-help formats. Each user receives personalized guidance after gameplay, making mental-health skill-building an interactive experience rather than a clinical one."},
  "SR003:nunu.ai": {"founded":2022,"overview":"nunu.ai builds AI agents that test and play games, replacing manual QA work and script-based automation for game developers. The agents interact with devices as a human would, covering tasks from bug detection and onboarding review to competitor analysis and player simulation, across PC, iOS, and Android. Game studios describe tasks in plain English and the agents execute them end-to-end at scale, around the clock."},
  "SR003:Orbital": {"founded":2024,"overview":"Orbital builds an entertainment company around a proprietary multimodal AI model trained for creative work. Its platform, Backlot, lets fans co-create content using Orbital's own intellectual property. The company replaces traditional IP-locked, studio-controlled content creation with a participatory model where audiences become collaborators."},
  "SR003:Refactor Games": {"founded":2021,"overview":"Refactor Games builds physics-driven sports video games, replacing the scripted animations of incumbent titles with a proprietary Sports Physics Engine that generates unique motion every frame. Current titles include a FIFA World Cup party game and Football Simulator, an early-access Unreal Engine 5 football game with a fully moddable environment. The studio targets both casual and simulation audiences across PC, console, and cloud platforms, backed by direct licensing relationships with sports leagues and athletes."},
  "SR003:RUNREAL": {"founded":2024,"overview":"RUNREAL builds a CI/CD and developer tooling platform purpose-built for Unreal Engine game studios. Its open-source CLI, build pipeline, and upcoming registry, monitor, and cloud services replace the manual, fragmented workflows game developers currently stitch together to compile, test, package, and distribute builds across engine versions and target platforms. The platform targets Unreal Engine developers who need automated, cross-platform build and delivery infrastructure without standing it up themselves."},
  "SR003:Schemata": {"founded":2023,"overview":"Schemata builds AI-driven virtual training and simulation software for defense and enterprise teams. It converts physical assets and operational data into photorealistic, interactive 3D environments where workers practice procedures, inspections, and maintenance tasks, replacing in-person, hardware-dependent training programs. An embedded AI instructor monitors learner actions and adapts guidance in real time, standardizing expert knowledge across an organization."},
  "SR003:Sekai": {"founded":2024,"overview":"Sekai builds an AI-powered platform for interactive content, starting with anime fan fiction. Fans write or imagine a story and the platform generates a playable, interactive version of it, replacing the manual work of writing, illustrating, and producing fan-made narratives. The long-term target is a broad interactive content feed, where any user-imagined scenario becomes a shareable, engaging experience."},
  "SR003:Soundmap": {"founded":2022,"overview":"Soundmap builds a social music app that lets users discover and share songs tied to real-world locations. It serves music listeners who want to explore what people are hearing in specific places, replacing passive playlist browsing with a geography-driven discovery experience."},
  "SR003:Spark Space": {"founded":2024,"overview":"Spark Space builds an AI writing tutor for K-12 students in grades 3 through 12. Students get personalized, interactive writing practice with immediate feedback, delivered through a gamified experience that adapts to their interests. Teachers get automated draft grading and class-level writing insights, cutting the time spent on manual review."},
  "SR003:TaleMonster Games": {"founded":2024,"overview":"TaleMonster Games builds mobile puzzle games that combine casual match-3 mechanics with hero progression and castle-defense strategy. Its debut title, Match Valley, targets players who want more depth than a standard casual game but without the friction of traditional mid-core titles. The team, veterans of Peak Games and Toon Blast, designed the game to run offline and deliver new episode content on a two-week cadence."},
  "SR003:TapTap Live": {"founded":2023,"overview":"TapTap Live builds social trivia games for Gen Z college students, starting with TapTap Trivia. The app offers daily live nationwide games and campus-level 1v1 battles, replacing static question banks with an AI content engine that pulls fresh questions from over 100 news sources each day. It modernizes a classic format so the content stays current with fast-moving culture."},
  "SR003:VRL": {"founded":2024,"overview":"VRL builds viral mobile games for consumer audiences. The founding team previously took NGL to the top of the App Store charts, and applies that playbook to new titles. Each game targets organic, rapid user growth, replacing the paid acquisition treadmill that most mobile studios depend on."},
  "SR004:Alpaka Games": {"founded":2024,"overview":"Alpaka Games builds hybrid-casual action mobile games, applying a rapid-testing studio model to the action genre. The team iterates on core mechanics quickly, combining proven gameplay loops with novel variations to avoid long production cycles. This replaces the traditional mobile game development approach of extended, costly builds before market validation."},
  "SR004:Atorie": {"founded":2024,"overview":"Atorie operates a marketplace connecting high-end manufacturers, including Italian leather and cashmere producers, directly to consumers at a fraction of traditional retail prices. Factories gain higher margins by bypassing conventional wholesale and retail chains, while shoppers access premium goods they would otherwise pay multiples more for at a brand-name retailer. AI tools handle merchandising, design, and personal shopping, replacing work typically done by editorial and wholesale teams."},
  "SR004:Checkmate": {"founded":2024,"overview":"Checkmate builds an AI-native vertical SaaS product targeting complex, high-impact problems in fintech. The company is in stealth, so the specific workflow or customer job it addresses is not yet public. It is founded by a former Google product manager and an AI researcher with prior experience building and exiting a startup."},
  "SR004:Cheddr": {"founded":2024,"overview":"Cheddr builds a real-money sports wagering app designed for casual bettors, operating legally in 46 states by running on a sweepstakes model that sidesteps the state-by-state licensing constraints that limit traditional sportsbooks. The platform targets the broad adult sports-betting audience, including users under 21 and those in states where conventional online sportsbooks are blocked. It replaces clunky, odds-table-heavy interfaces with a simplified UI, in-game micro-betting, and social and gamification features built around live NFL action."},
  "SR004:Chronicler": {"founded":2024,"overview":"Chronicler builds an AI assistant that lives inside messaging apps, turning self-sent notes, reminders, and voice memos into an organized, searchable personal knowledge base. It handles task management, deadline reminders, and calendar updates through plain-text chat, replacing dedicated to-do apps and note-taking tools for individuals who already capture thoughts by texting themselves."},
  "SR004:Circle Games": {"founded":2024,"overview":"Circle Games builds mobile puzzle games for casual players, targeting mechanics with strong market growth. Its current title, Sort Express, tasks players with organizing and matching 3D objects across escalating levels. The studio replaces generic puzzle templates with tightly tuned core mechanics, social systems, and mini-games designed to drive long-term retention."},
  "SR004:Clubs Poker": {"founded":2023,"overview":"Clubs Poker builds an online sweepstakes poker and casino platform where players across the United States compete in real-money-style tournaments and cash games without requiring a purchase to play. The platform covers a wide range of poker formats, from Texas Hold'em and Omaha to mixed games and progressive knockout tournaments, replacing both physical card rooms and traditional real-money poker sites. It targets casual players and high-stakes enthusiasts who want accessible, prize-eligible poker available in states where regulated online gambling is restricted."},
  "SR004:Coverd": {"founded":2025,"overview":"Coverd builds a gamified spending platform that turns everyday purchases into chances to win cash back or prizes. Users play free casino-style games, rip collectable card packs, and hold a Visa credit card with variable cash-back rates, all under a single account and app. The product replaces flat, passive rewards programs with an active, game-driven loop designed to make personal finance engaging."},
  "SR004:Coverstar": {"founded":2023,"overview":"Coverstar builds a social platform for kids aged 9 to 16, combining short-form video creation, AI-powered personal avatars, and multiplayer social games in a single app. It replaces general-purpose platforms like TikTok with a purpose-built alternative that has no direct messages, proactive AI and human moderation, and content designed around daily creative challenges rather than passive feed scrolling. Parents and regulators are the secondary audience the safety architecture is built to satisfy."},
  "SR004:Darwin": {"founded":2024,"overview":"Darwin builds a search and execution layer for the agentic web, indexing AIs, software, services, experts, and products so that humans and AI agents can find the right capability for a given goal and act on it directly. It replaces fragmented, manual discovery across tools and marketplaces by resolving an intent, shaping scope and terms, and coordinating the work through to completion."},
  "SR004:Dial": {"founded":2025,"overview":"Dial gives AI agents a real phone number with access to voice calls, SMS, iMessage, and WhatsApp through a single API. It targets developers and teams shipping agents into production who would otherwise spend months building their own telephony layer from scratch. The product removes the blocker that stops agents cold when a workflow requires receiving a verification code or placing a call."},
  "SR004:Double Dusk": {"founded":2024,"overview":"Double Dusk builds two-player cooperative video games designed to grow alongside long-term friendships. Each title pairs character-driven design with mechanics that encourage repeated, social play, replacing the solitary or large-group formats that dominate the current market. The studio targets players who want a dedicated co-op experience built specifically for pairs rather than adapted from solo or squad formats."},
  "SR004:Double Fifth": {"founded":2024,"overview":"Double Fifth builds a unified API that gives developers structured access to users' personal data held across third-party platforms, such as watch history, order history, and ride data. It handles the scraping, connector maintenance, and schema normalization that would otherwise fall to each development team. The API targets use cases like onboarding flows and personalization engines that depend on real behavioral history rather than self-reported inputs."},
  "SR004:Edgar": {"founded":2024,"overview":"Edgar builds a sweepstakes-powered game engine that brings real-money engagement to free-to-play games. Its first product is a next-generation social casino developed in partnership with Betty Gaming. The engine replaces conventional F2P monetization with sweepstakes mechanics that give players a stake in outcomes without requiring a traditional gambling license."},
  "SR004:Figment": {"founded":2025,"overview":"Figment builds an end-to-end platform for AI-powered interactive storytelling, combining a consumer app with professional authoring tools for visuals and narrative. Readers and creators use it to produce stories that adapt in real time, replacing static, linear formats with personalized, open-ended worlds. The team's background spans Pixar and Epic Games, grounding the technology in both cinematic craft and interactive experience design."},
  "SR004:FLORA": {"founded":2024,"overview":"FLORA builds an agentic creative workspace that unifies leading text, image, and video AI models on a single infinite canvas. Visual design teams use it to concept, generate variations, and share production-ready generative workflows with clients, replacing the manual work of stitching together separate AI tools. The product targets professional creative agencies as its primary user."},
  "SR004:Ghosted": {"founded":2024,"overview":"Ghosted builds a dating app for Gen Z that enforces an unedited-photos-only policy, using AI to detect and remove filtered, retouched, or AI-generated images before they reach other users. It replaces the heavily curated, filter-laden experience common on mainstream dating apps with dynamic, story-style profiles that show people as they actually look. The goal is to eliminate the gap between someone's profile and the person who walks through the door."},
  "SR004:Greathorn Games": {"founded":2024,"overview":"Greathorn Games builds socially-driven multiplayer games for PC and console that are designed to spark conversation between players. Where most multiplayer titles treat communication as a side effect, Greathorn makes it a core mechanic, with systems that push players to talk through tactics and strategy during play. Deep integrations with Discord and similar platforms extend that social layer beyond the session to build lasting communities."},
  "SR004:Hooper": {"founded":2024,"overview":"Hooper turns a smartphone into a personal sports media crew for recreational basketball players. The app uses video AI to automatically generate game highlights, stats, mixtapes, and leaderboards, replacing the camera operators, editors, and tracking systems that only professional teams could previously afford. Athletes get pro-level storytelling and performance data from a pickup game with nothing beyond the phone already in their pocket."},
  "SR004:Intangible": {"founded":2024,"overview":"Intangible builds an AI-native 3D studio for creative teams producing high-stakes visual work across advertising, film, retail, events, architecture, and deep tech. Users build scenes from their own assets and CAD references, direct cameras and animation, and generate pro-quality renders, replacing the complexity and cost of traditional 3D tools like Autodesk or game engines. A proprietary spatial intelligence engine gives generative models a semantic understanding of objects and space, eliminating the hallucinations and loss of control that come with prompt-only workflows."},
  "SR004:Kitbash": {"founded":2024,"overview":"Kitbash builds Lark, a realtime database for web apps, games, and mobile applications that need state synced across large numbers of concurrent users. It targets developers who rely on Firebase Realtime Database, replacing it with a drop-in compatible alternative that requires changing a single config variable. Teams can run Lark on Kitbash's cloud hosting or self-host the open-source version."},
  "SR004:Layerpath": {"founded":2024,"overview":"Layerpath turns a single recorded browser workflow, video, or image set into interactive product tours, step-by-step guides, and training videos. Product, marketing, sales, and customer success teams use it to document and teach software without rebuilding walkthroughs from scratch each time the product changes. It replaces manual screen recording, slide decks, and live walkthrough calls."},
  "SR004:Mara": {"founded":2024,"overview":"Mara builds autonomous counter-drone systems for military and critical infrastructure operators facing coordinated FPV drone attacks. Its first product, Spike, is a portable, low-cost interceptor system that provides hemispherical 360-degree coverage in RF-contested, GPS-denied environments, handling detection and defeat without requiring operator input. The autonomy stack is trained inside a video game, using simulation and player data to develop tactics that adapt continuously, replacing slower, centralized, and more expensive traditional counter-UAS approaches."},
  "SR004:Marlo": {"founded":2025,"overview":"Marlo builds an AI agent for talent agencies and creators that sits inside email inboxes and social DMs to manage brand deal flow end to end. It ingests historical threads to construct a deal graph, scores new inbound against past performance, drafts replies, and tracks deliverables and payments. The work it replaces is the manual triage, outreach, and coordination that talent coordinators handle across high volumes of brand partnership inquiries."},
  "SR004:Mini Studio": {"founded":2022,"overview":"Mini Studio builds personalized animated films for young children, placing each child as the protagonist using a single uploaded photo. Parents choose from themed stories covering milestones like starting school, bedtime routines, and building confidence, replacing generic children's media with narratives written by child development experts. The product targets families seeking keepsakes and emotionally resonant content tied to specific moments in a child's early life."},
  "SR004:Moku": {"founded":2021,"overview":"Moku builds a launch and distribution platform for web3 game developers, letting studios take a game from MVP to paying users without the usual publishing overhead. Developers list their game, attract early players who buy and trade in-game assets, and collect revenue from day one. The platform replaces the cold-start problem of finding an aligned early audience and setting up monetization infrastructure."},
  "SR004:Nativ": {"founded":2024,"overview":"Nativ adapts visual and audio content, including images, video, and graphics, for brands expanding into new regional markets. Its AI platform goes beyond text translation to rework the cultural framing of creative assets so they resonate with local audiences, replacing the manual, agency-driven localization process. Brand and marketing teams use it to produce market-specific content from a single master asset across dozens of languages and cultures."},
  "SR004:Nexad": {"founded":2024,"overview":"Nexad builds AI-native marketing products for growth teams running paid ads across Google, Meta, TikTok, and ChatGPT Ads. Its flagship product, Soku AI, is an autonomous marketing agent that continuously analyzes performance, generates and tests ad creative, and applies optimizations around the clock, replacing the manual work done by agencies and human media buyers. The system operates a perceive-decide-act loop and escalates decisions to the user only when human judgment is required."},
  "SR004:Nilo": {"founded":2024,"overview":"Nilo builds a browser-based generative AI platform that lets players create 3D models, worlds, and animations from text prompts, sketches, or images in seconds. It targets young creators, particularly those building for Roblox, replacing traditional 3D modeling pipelines with instant generation, rigging, and animation tools. Creators share and play in their worlds together via a simple link, on desktop, mobile, or chat platforms."},
  "SR004:o1.exchange": {"founded":2024,"overview":"o1.exchange builds a unified onchain trading platform for crypto traders who need a full-stack venue in one place. It combines a multi-order-type terminal (spot, limit, sniper, and TWAP), a meta-aggregated cross-chain swap, and a token launchpad built on Uniswap v4. The launchpad replaces the standard fair-launch setup with permanent on-chain liquidity and a decaying fee structure that penalizes snipers rather than rewarding them."},
  "SR004:Outcome": {"founded":2022,"overview":"Outcome builds TeamOS, a platform that helps large companies eliminate the coordination drag that accumulates as they grow. It ingests activity data from tools teams already use, such as Jira, GitHub, and calendars, and maps it into a knowledge graph that surfaces where work is blocked by cross-team dependencies. AI-driven recommendations then tell operators what to change in team structure, ownership, or priorities to restore flow, replacing the work of periodic org-design consultants and manual retrospectives."},
  "SR004:Plots": {"founded":2023,"overview":"Plots builds an event discovery platform for Gen Z, surfacing local in-person events and the people attending them. It replaces passive social feeds and generic listings by connecting users to curated real-world experiences and the social layer around those events."},
  "SR004:Rehearsals": {"founded":2024,"overview":"Rehearsals builds a self-serve simulation platform that lets marketing and product teams test decisions against AI digital twins of real customers. Teams upload ad creatives, pricing concepts, or product flows and get predicted outcomes across thousands of parallel simulations in minutes. The platform replaces traditional research cycles: focus groups, surveys, and waiting weeks for customer feedback on pricing, messaging, churn, and launch strategy."},
  "SR004:Sitch": {"founded":2023,"overview":"Sitch builds an AI-assisted matchmaking service for singles who want a more curated alternative to swipe-based dating apps. It pairs AI with human matchmakers to handle the search and screening work that users would otherwise do themselves through endless app browsing or chance encounters. The product targets people frustrated by low-quality matches and conversations that go nowhere on conventional dating platforms."},
  "SR004:Spekter Games": {"founded":2024,"overview":"Spekter Games publishes games on Telegram and its own platform, Spekter.xyz, targeting mainstream players who currently play mobile and browser-based titles. Its first slate starts with rogue-lite games distributed through Telegram, where blockchain features run in the background rather than as a central mechanic. The studio is also building AI-native open-world RPGs in which a conversational AI game master runs within authored world rules, replacing the static quest and dialogue systems traditional RPGs rely on."},
  "SR004:Sunflower": {"founded":2024,"overview":"Sunflower builds a sobriety support app for people managing addiction, replacing or supplementing human sponsors and therapists. The product combines an AI sponsor, CBT-based journaling, visual progress tracking, and educational content into a single toolkit. It targets the broad population of individuals seeking structured, ongoing support for recovery."},
  "SR004:SweatPals": {"founded":2022,"overview":"SweatPals builds a marketplace for grassroots fitness communities, connecting people who want to discover local run clubs, workout groups, and wellness events with independent hosts who create and lead them. It gives community organizers tools to list, manage, and monetize their offerings, replacing the patchwork of group chats, manual signups, and word-of-mouth coordination that most grassroots fitness hosts rely on today."},
  "SR004:Talus Robotics": {"founded":2024,"overview":"Talus Robotics builds robotic guide dogs for blind and visually impaired people, replacing trained animal guides that cost roughly $80,000 and are out of reach for the vast majority of those who need them. Its robotic alternative delivers the same navigation assistance at a fraction of the price. The company plans to extend the same platform into elder care and emotional support."},
  "SR004:trophi.ai": {"founded":2022,"overview":"trophi.ai builds Kairos, a real-time AI coaching platform for high-skill, high-stakes domains. Kairos observes a learner's performance, identifies critical decision points, and delivers expert-level verbal guidance in under a second, replacing or augmenting human instructors in sim racing, commercial and defense aviation, oil and gas operations, and drone qualification. The platform does the work of a dedicated human instructor: watching, interpreting, and intervening at the exact moment feedback can change the outcome."},
  "SR004:Unbound": {"founded":2022,"overview":"Unbound builds a 3D creation and game development tool built on signed distance fields (SDF), replacing the mesh-based architecture that has underpinned professional 3D software for decades. It targets both newcomers and experienced developers who want to model assets, add game logic, and publish playable games, without the complexity of traditional tools like Blender or Unity. The longer-term goal is a web-scale platform where anyone can create, share, and remix interactive 3D content."},
  "SR004:Valor": {"founded":2023,"overview":"Valor builds an automatic cashback platform for active-duty military, veterans, and their families. Members link an existing payment card once, and Valor detects eligible purchases at participating local businesses and deposits cashback without requiring the member to ask, present an ID, or show proof of service. The product replaces the manual, often awkward process of claiming military discounts at the point of sale."},
  "SR004:Waveful": {"founded":2025,"overview":"Waveful builds an AI-powered social app for creators and fans to form communities, share content, and earn from their audience. AI tools handle discovery and distribution, lowering the bar for ordinary people to build a following without relying on established platform algorithms. The product targets creators who want to grow an audience and monetize it, replacing the manual grind of cross-posting and community management on legacy social platforms."},
  "SR005:Agent Astra": {"founded":2022,"overview":"Agent Astra builds an AI-native freight forwarding platform that owns and operates the logistics businesses running on it. The platform gives freight operators tools to move containers, track shipments, and manage complexity with a fraction of the headcount traditional brokers and forwarders require. It targets the full service range of a global logistics provider while compressing the workforce needed to deliver it."},
  "SR005:Ambiguous AI": {"founded":2025,"overview":"Ambiguous AI builds a unified productivity workspace where AI agents and human teammates work side by side in the same apps on the same data. The suite covers 17 tools, including Docs, Mail, Chat, Sheets, CRM, and Calendar, each designed so every action a person can take an agent can also take natively. It replaces the hand-off friction of bolting AI onto existing tools by treating agents as first-class coworkers from the ground up."},
  "SR005:Anchr": {"founded":2025,"overview":"Anchr builds a workforce of AI agents for food distributors and other physical operations businesses, automating the manual, repetitive work that runs across order intake, procurement, inventory management, and vendor coordination. Each agent plugs into the distributor's existing systems and handles discrete operational tasks, replacing the human hours spent routing orders, matching invoices, chasing vendors, and resolving unit discrepancies. The product targets the operational core of distribution businesses, where errors and delays compound across every transaction."},
  "SR005:AndThen": {"founded":2025,"overview":"AndThen builds a voice-first interactive entertainment platform where users play through short, episodic experiences, such as game shows, mysteries, and character-driven stories, by speaking aloud. Each format is designed to be replayable and structured around real goals, replacing passive audio content with conversation-driven gameplay. Creators, writers, celebrities, and brands publish formats on the platform, with user-generated publishing on the roadmap."},
  "SR005:Argu AI": {"founded":2024,"overview":"Argu AI builds a natural-language video intelligence platform that turns existing CCTV cameras into configurable monitoring agents. Security and operations teams at ports, utilities, government facilities, and commercial venues describe what they want to detect in plain text, and the system creates alerts, searches, and analytics across thousands of cameras without writing code or retraining models. The product replaces lengthy procurement cycles, custom model development, and fixed preset-based surveillance systems."},
  "SR005:Arise Labs": {"founded":2025,"overview":"Arise Labs builds an AI investment analyst that ingests unstructured data, constructs auditable investment theses, and executes decisions with the rigor of an institutional analyst. It targets portfolio managers and investors, replacing the manual research and decisioning work typically done by human analyst teams. The system is designed to run continuously, delivering institutional-grade coverage at any scale."},
  "SR005:Artifact AI": {"founded":2024,"overview":"Artifact AI builds an AI agent platform for accounting and professional services firms, automating the manual work of bookkeeping, ledger posting, reconciliation, and financial close. It replaces human-hours spent on transaction review and reporting by deploying purpose-built agents that score entries, generate audit trails, and surface real-time client metrics. The target customer is the accounting firm looking to increase capacity without adding headcount."},
  "SR005:Atrios": {"founded":2025,"overview":"Atrios turns well-connected individuals into a paid referral network for B2B software companies. Tastemakers share personalized links to vetted SaaS products and earn flat fees per booked meeting and larger payouts when a deal closes. The platform replaces cold outbound sales with warm introductions from people who already have relevant relationships."},
  "SR005:Avenir AI": {"founded":2025,"overview":"Avenir AI builds AI agents that automate employee benefits management for self-insured employers and benefits brokers. The product analyzes claims, utilization, and regulatory data to optimize plans and vendor decisions, replacing the manual work brokers and HR teams currently do by sifting through large, fragmented datasets. It targets a market where legacy systems have made benefits administration both costly for employers and opaque for employees."},
  "SR005:Axon": {"founded":2024,"overview":"Axon builds brain-inspired AI models for high-frequency financial trading, where speed of prediction is the competitive edge. Its architecture anticipates market moves before full data arrives, cutting latency at both the model and infrastructure layers. The firm targets trading workflows that conventional low-latency systems and standard deep learning models handle separately, combining both into a single research-led stack."},
  "SR005:Bead AI": {"founded":2025,"overview":"Bead AI builds AI agents for internal audit teams, starting with Sarbanes-Oxley compliance testing. The agents collect evidence from source systems, validate submitted files, execute existing testing plans step by step, and produce marked-up working papers, replacing the manual document chasing, screenshot comparisons, and spreadsheet population that consume most of an auditor's time. The target customer is any US-listed company running an internal SOX audit program."},
  "SR005:bins": {"founded":2025,"overview":"bins builds a peer-to-peer secondhand marketplace designed to replace the scroll-and-search model of platforms like Depop and Poshmark. Each morning, users receive a curated, finite set of resale clothing collections, called bins, rather than an open-ended catalog. The product targets style-conscious shoppers and casual sellers who want the tactile surprise of thrift-store browsing without leaving their phone."},
  "SR005:BotBot": {"founded":2025,"overview":"BotBot gives non-technical teams, brand, design, marketing, and product, direct control over voice AI behavior without engineering tickets. Teams edit tone, pacing, persona, and upsell timing in plain English, run A/B tests against live customer conversations, and read the results in metrics like ticket size, CSAT, and containment. The product replaces static, launch-day configuration that otherwise runs unchanged on every call until someone files a ticket to change it."},
  "SR005:Brief": {"founded":2024,"overview":"Brief builds a product-context layer for AI coding agents, giving them access to the decisions, requirements, and institutional knowledge that live across tools like Linear, Jira, Notion, Slack, and GitHub. Product and engineering teams use it to keep agents aligned with existing product intent rather than letting them build against stale or missing context. It replaces the manual work of re-explaining decisions to every agent and the rework that follows when agents build without that grounding."},
  "SR005:Color": {"founded":2023,"overview":"Color builds an engine that brings AI to life by fusing a AAA game engine with multimodal machine learning models. The engine powers Color's first consumer app, Otherhalf.ai, an AI companion designed for human presence and connection rather than information retrieval. This replaces the text-only, question-and-answer model that defines most AI products today."},
  "SR005:Creed": {"founded":2025,"overview":"Creed builds a Christian AI companion app for everyday believers, pastors, and ministry leaders. Users can ask faith questions by text or voice, with every response grounded in Scripture alongside readable verse references. The app replaces ad-hoc Google searches and generic devotional content with guided daily prayer, journaling, Bible reading, and plain-language Scripture explanation built around Christian values."},
  "SR005:Dex": {"founded":2025,"overview":"Dex builds an AI recruiter and career coach for software engineers, replacing the standard CV-and-job-board process with a conversational intake that maps each engineer's ambitions, motivations, and deal-breakers. It uses that profile to match engineers with tech companies and introduce them directly to hiring managers. On the company side, Dex surfaces pre-qualified, often passive candidates who are matched on fit rather than keyword overlap."},
  "SR005:Dispatcher": {"founded":2025,"overview":"Dispatcher builds an aerial intelligence platform that converts commercial drones into autonomous agents capable of making real-time decisions without a human operator in the loop. Security teams, construction sites, agricultural operations, and heavy industry use it for automated perimeter patrols, incident response, and asset monitoring, replacing manual drone piloting and after-the-fact data review. Operators issue commands in natural language and receive live alerts, heatmaps, and reports through app, SMS, and dashboards."},
  "SR005:doublespeed": {"founded":2025,"overview":"doublespeed builds autonomous social media accounts that post, engage, and grow audiences on TikTok and Instagram around the clock. Brands and marketers use it to drive organic attention at scale across any demographic niche, replacing the human labor of creator sourcing, content production, and community engagement. Each agent learns from performance data over time, making future content more effective."},
  "SR005:EverCurrent": {"founded":2025,"overview":"EverCurrent builds an AI-native platform of record for hardware engineering teams, connecting bills of materials, ECOs, handoffs, and team decisions into a single view. It automatically documents changes across tools and teams, ties each decision to its broader context, and surfaces dependency risks before they become costly. The product replaces fragmented, manual tracking of hardware changes that leaves teams blind to downstream impacts."},
  "SR005:Ezra AI Labs": {"founded":2024,"overview":"Ezra AI Labs builds a voice AI interviewer for corporate recruiting teams, replacing the initial human screening call. Recruiters send candidates a structured voice interview conducted by the AI, which captures spoken responses that resume reviews and text-based screens cannot surface. The product targets the gap created by AI-generated resumes and coached answers by evaluating candidates on nuance and authenticity at scale."},
  "SR005:Fearn": {"founded":2025,"overview":"Fearn handles patent prosecution for startups, replacing the slow, expensive billing model of traditional Big Law firms. Former Big Law patent attorneys review every filing, and AI handles the drafting work that previously drove up hours and cost. Startups get portfolio-grade patents on days-long turnarounds instead of quarters-long ones."},
  "SR005:First Voyage": {"founded":2025,"overview":"First Voyage builds a mobile self-care app centered on Momo, an AI-powered mythological creature that turns daily wellness habits into a game. Users complete small quests around sleep, journaling, and personal routines, earning in-app coins to customize Momo and its world. The product replaces passive habit trackers with an immersive, character-driven loop designed to keep people returning to their routines daily."},
  "SR005:Forgepoint": {"founded":2025,"overview":"Forgepoint builds AI agents for the manufacturing back office, starting with Frank, an AI inside sales rep that handles the full RFQ-to-quote workflow for job shops and industrial manufacturers. Frank qualifies incoming requests, prices parts against the shop's cost model, sends quotes for human approval, follows up with customers, and logs every action to the CRM and ERP. It replaces the manual quoting work done by sales reps, estimators, and engineers across injection molding, metal fabrication, CNC machining, and adjacent trades."},
  "SR005:General Magic": {"founded":2024,"overview":"General Magic builds a suite of insurance-specific AI agents that handle the operational workload inside insurance brokerages: underwriting questions, customer servicing, and compliance review. Edward answers appetite and eligibility questions by citing carrier manuals directly, replacing manual document searches. Ava services policyholders around the clock over email, text, and voice, handing off to a licensed broker with full context when needed, while Peter reviews every conversation for quality and compliance."},
  "SR005:Jigsaw": {"founded":2025,"overview":"Jigsaw builds post-training data for recursive self-improvement, selling to frontier AI labs working toward advanced AI systems. The team converts AI research and development into verifiable, gradable tasks, then supplies the resulting artifacts as post-training data, replacing the ad-hoc and hard-to-evaluate methods labs currently use to generate training signal for self-improving models."},
  "SR005:Jooba": {"founded":2025,"overview":"Jooba runs end-to-end recruiting for high-growth teams, replacing the work done by traditional staffing agencies and in-house recruiters. AI agents handle sourcing, outreach, scheduling, and reporting, while hiring managers review shortlisted candidates and schedule interviews directly inside Slack. The product targets the top of the hiring funnel, delivering vetted candidates without requiring teams to manage the search themselves."},
  "SR005:Kanu AI": {"founded":2025,"overview":"Kanu AI builds an enterprise AI platform that converts repeatable internal workflows into purpose-built software driven by a firm's own data, documents, and institutional knowledge. It targets data-heavy financial services verticals, including commercial real estate, private equity, insurance, and financial services, replacing manual research, analysis, and reporting work that teams currently do by hand. The platform connects disparate data sources, lets users query them in plain language, and delivers finished outputs in the formats teams already use."},
  "SR005:Kintow": {"founded":2024,"overview":"Kintow automates back-office operations for restaurants, connecting fragmented point solutions, such as POS, scheduling, invoicing, and banking, into a single system that tracks food costs, labor, and cash flow. It replaces manual forecasting and ordering by anticipating demand and sending vendor orders automatically, freeing managers from spreadsheet work. The target customer is multi-location restaurant operators whose general managers currently juggle disconnected tools to run daily operations."},
  "SR005:Lekondo": {"founded":2025,"overview":"Lekondo builds a social platform centered on fashion, giving consumers a dedicated space to discover, discuss, and engage with style outside of general-purpose social networks. The product targets fashion enthusiasts and replaces scattered fashion conversation that currently happens across mainstream social media."},
  "SR005:Limy AI": {"founded":2025,"overview":"Limy AI builds an AI Search platform for brand marketers, showing them how AI agents discover, cite, and recommend their brand across AI-powered search experiences. It replaces guesswork about AI-driven discovery with attribution, analytics, and visibility tools that connect agent behavior on a site to downstream customer actions. Marketers use it to find gaps in their AI Search presence and measure the traffic and revenue that result."},
  "SR005:Loan Labs": {"founded":2024,"overview":"Loan Labs builds AI workers for mortgage companies, starting with LOIS, an AI loan processing assistant. LOIS collects and organizes borrower documents, extracts structured data, flags inconsistencies, and automates borrower follow-up, replacing the manual work done today by loan processors and underwriters across fragmented email, CRM, and loan origination systems."},
  "SR005:Logical Health": {"founded":2025,"overview":"Logical Health builds an AI-driven member engagement platform for health insurers and healthcare organizations. It replaces one-way outreach, such as unanswered calls and unopened emails, with two-way text conversations that identify the specific barrier keeping a member from acting and resolve it in the same thread. Underneath the conversational layer sits a rules engine that converts insurance policy language into precise, machine-readable logic to answer coverage questions accurately."},
  "SR005:Luvu": {"founded":2025,"overview":"Luvu builds a human data foundation that backs frontier AI systems, giving AI agents grounded, people-centered context to draw on. The product targets consumer-facing AI applications where understanding human behavior and preference is the core input. It replaces ad hoc data curation and hand-labeled behavioral datasets that teams otherwise assemble manually."},
  "SR005:Margin": {"founded":2025,"overview":"Margin builds AI-native credit card infrastructure that lets consumer brands offer dynamically personalized rewards, replacing the static, one-size-fits-all loyalty programs that traditional card issuers run. The platform analyzes individual spending behavior in real time and adjusts rewards to match each cardholder's preferences. Margin is extending the model beyond credit cards toward a broader suite of personalized consumer credit products."},
  "SR005:Metal": {"founded":2023,"overview":"Metal builds an end-to-end fundraising platform for founders, combining industry data with company-specific context to run the workflows that make up a capital raise. It replaces the spreadsheets, manual research, and disconnected outreach tools founders typically stitch together when going out to investors."},
  "SR005:Moescape AI": {"founded":2023,"overview":"Moescape AI builds an all-in-one creative platform for anime fans, letting users design original characters and then generate images, videos, music, and voice output from them in a single environment. Fans can also chat with their characters through an LLM-powered roleplay system. The platform replaces a fragmented workflow that previously required separate tools for art generation, voice synthesis, video creation, and interactive fiction."},
  "SR005:Moona Health": {"founded":2024,"overview":"Moona Health builds a virtual network of CBT-I therapists who treat chronic insomnia online, covered by insurance. Patients work one-on-one with licensed clinicians through a short course of cognitive behavioral therapy for insomnia, replacing sleep medication and unguided wearable apps. Behind the clinicians, an AI platform handles insurance claims, scheduling, and sleep data analysis to give therapists personalized session guidance."},
  "SR005:Nexxa.ai": {"founded":2023,"overview":"Nexxa.ai builds agentic AI software for heavy industrial enterprises, automating critical engineering and operational workflows that today depend on institutional knowledge held by individual workers. Its AI agents write directly into customers' existing systems of record, replacing the slow, manual decision cycles typical of generic ERP platforms and consulting engagements. The result is software purpose-built for a single operation, maintained continuously by AI, and owned outright by the customer."},
  "SR005:Ocoder": {"founded":2025,"overview":"Ocoder builds an AI-powered development environment for designers and product managers who need to work directly with real codebases. It lets non-technical team members prototype and build new features without engineering support, then share results with engineers and stakeholders via shareable links. The product replaces back-and-forth communication cycles where non-technicals previously had to relay ideas through developers to see them realized."},
  "SR005:Oleum": {"founded":2025,"overview":"Oleum builds AI tools that let business users query, explore, and act on data without relying on specialized analysts or engineering pipelines. Built by a team of former quantitative researchers, the platform targets data-oriented businesses that need faster, more accessible insight from their existing data. It replaces manual data wrangling, ad hoc analyst requests, and bespoke internal tooling."},
  "SR005:Pen.dev": {"founded":2025,"overview":"Pen.dev builds an agentic design canvas that lives inside a codebase, letting engineers design UI without handing off to a separate design tool or team. Agents create, refine, and iterate on layouts directly on the canvas, replacing the back-and-forth between Figma files and code editors. It connects to Cursor, Claude Code, VSCode, and OpenAI Codex through MCP, and stores designs in an open format alongside the code."},
  "SR005:Prepp": {"founded":2025,"overview":"Prepp builds AI-powered modules for students and educators, handling tasks that traditionally require manual effort: generating course materials, grading assignments, tracking attendance, and driving student engagement. The product targets both the administrative burden on teachers and the content delivery experience for learners, replacing disconnected, labor-intensive workflows with a unified toolset."},
  "SR005:Presia": {"founded":2025,"overview":"Presia builds AI agents for management consultants, automating the manual, process-heavy work that consumes time consultants would otherwise spend on analysis and client problem-solving. The product targets consulting firms and enterprise clients, replacing the routine document, research, and synthesis tasks that make up the bulk of a typical engagement's labor."},
  "SR005:Rork": {"founded":2024,"overview":"Rork lets non-technical founders build, install, and publish native iOS, Android, and web apps by chatting with AI, replacing the need to write code or hire mobile developers. Users describe what they want and Rork generates production-ready Swift or Kotlin apps that can be submitted directly to the App Store or Google Play. The product targets aspiring app founders who want to go from idea to a live, monetizable app without an engineering background."},
  "SR005:Sans Strings Studio": {"founded":2023,"overview":"Sans Strings Studio produces transmedia entertainment, building stories and IP across games, film, social, and live events from a single shared asset pipeline. Its F.E.L.T. system lets IP holders generate both interactive and linear content simultaneously, replacing the separate production workflows each format normally demands. The studio targets the gap between rising content demand and rising production cost, using real-time technology to scale output while keeping human creative authorship intact."},
  "SR005:Shockwave": {"founded":2024,"overview":"Shockwave builds an AI-powered daily games platform targeting the casual gaming market. The platform delivers a growing roster of daily games across multiple genres, competing in the space that hits like Wordle opened up. It replaces one-off game downloads and ad-hoc play with a single destination for recurring daily engagement."},
  "SR005:Sonatic": {"founded":2025,"overview":"Sonatic builds a desktop AI assistant for knowledge workers that watches how a user works across their tools, learns their patterns, and then executes routine tasks on their behalf without manual commands. It targets the repetitive coordination and execution work that currently consumes workers' time in apps like email, project management, and other workplace software. The product replaces the manual, step-by-step task completion that workers would otherwise do themselves."},
  "SR005:SoulLink": {"founded":2025,"overview":"SoulLink builds AI companion apps that give users a persistent, cinematic virtual relationship. The product pairs 3D character rendering drawn from AAA game production with an emotional AI layer that retains conversational history across sessions. It targets consumers seeking ongoing social connection, replacing the flat, stateless chat experience of earlier virtual companion tools."},
  "SR005:Sounding": {"founded":2025,"overview":"Sounding builds voice-first AI wellness apps for consumers, targeting the adherence problem: getting people to follow through on health behaviors over time. The product replaces passive content and manual check-ins with an interactive voice experience that guides users through real-world wellness routines."},
  "SR005:Sourcerer": {"founded":2025,"overview":"Sourcerer acts as an AI-native, full-stack distributor for companies buying physical goods across global supply chains. Its autonomous agents handle the entire procurement cycle: vetting factories, negotiating prices, arranging freight, and offering trade credit, then issuing a single consolidated quote. The product replaces the manual RFQ process, broker relationships, and spreadsheet-and-email workflows that traditional distributors rely on."},
  "SR005:Syzygy": {"founded":2025,"overview":"Syzygy builds ultra-compressed, task-specific AI models and the local inference stack to run them on Apple Silicon, targeting enterprises and developers who want to own their AI layer instead of routing queries through third-party API vendors. Its Mach 1 Additive architecture runs a 35B mixture-of-experts model at 1.7 bits per weight, retaining 96.3% of full-precision benchmark scores while fitting on a 16 GB Mac. The product bundle spans a desktop coworking app, a local inference engine, and a TypeScript agents SDK, replacing cloud inference calls with on-device, proprietary model deployments."},
  "SR005:Taya": {"founded":2024,"overview":"Taya builds a jewelry-form-factor AI wearable for everyday consumers who want to capture and revisit fleeting thoughts without reaching for a phone. The product, a stainless steel pendant on a 14K gold-plated chain, lets wearers press a button, speak naturally, and retrieve those moments later through a companion app. It replaces the habit of typing notes mid-task or losing ideas entirely when attention is already divided."},
  "SR005:URSA Mining": {"founded":2024,"overview":"URSA Mining builds an autonomous operating system for mining equipment, converting existing excavators and earth-movers into self-directing robots without requiring new hardware purchases. The system targets mine operators contending with a retiring skilled workforce, decade-long development timelines, and production costs that consume the majority of operating budgets. It replaces human-operated and manually supervised earth-moving with software-driven autonomy, and tracks material movement from pit extraction to final destination."},
  "SR005:Variant": {"founded":2025,"overview":"Variant builds a social platform that converts text, memes, and doodles into shareable, remixable mini-games. It targets creators and community builders who want to turn everyday content, jokes, fan fiction, or casual ideas into interactive experiences without any game-development work. The platform replaces static posting with playable, living content that communities can remix, battle over, and publish across TikTok, Discord, and Reddit."},
  "SR005:Vega": {"founded":2025,"overview":"Vega builds a relationship intelligence app that turns user-written notes about friends into curated social groups, called orbits, matched by mutual trust and shared experiences. Users trade notes on the people in their lives to receive AI-generated introductions and context about their own network. The product replaces the manual, hit-or-miss work of figuring out who in your extended circle is worth knowing better."},
  "SR005:YKB": {"founded":2024,"overview":"YKB builds a social prediction app for sports fans, letting them log takes, compete with friends, and hold each other accountable when outcomes land. An AI agent generates interactive prompts called Receipts whenever news breaks, replacing the informal, forgettable group-chat argument with a structured, timestamped record of who said what. Starting with NFL, the product targets the broader culture fan who wants bragging rights, not a betting account."},
  "SR005:Zero Billion": {"founded":2024,"overview":"Zero Billion runs a consumer research lab that ships AI-powered consumer apps, observes how people use them at scale, and sells the resulting behavioral data to model developers. The marketplace pays contributors directly via Stripe for audio, video, screen recordings, calls, and other everyday human data, on a consent-first, revocable basis. The studio arm replaces traditional media production pipelines by letting anyone generate short-form TV-style shows in under an hour for a fraction of conventional production cost."},
  "SR005:Zingroll": {"founded":2024,"overview":"Zingroll operates a streaming platform for AI-generated movies and series, built for creators who produce shows entirely with generative AI tools. Viewers watch original AI-made content from a global pool of creators, replacing the traditional studio and production pipeline that previously stood between a creative person and a distributed audience."},
  "SR006:Acceler8": {"founded":2025,"overview":"Acceler8 builds an agentic AI platform that gives executives continuous, real-time answers to workforce planning questions: which roles to automate, where to redeploy people, and how to structure an organization as AI agents take on more work. The decisions it replaces were previously handled through spreadsheets, outside consultants, and static HR systems, a process that took months and produced plans already obsolete on delivery."},
  "SR006:Advocate": {"founded":2025,"overview":"Advocate builds an AI voice assistant for seniors and their families, handling everyday requests, such as rides, groceries, home repairs, and appointments, end to end over a single phone number. Family members receive text updates when tasks are completed, and Advocate proactively calls seniors to catch problems early. A shared record keeps the full picture visible to everyone involved, replacing the informal coordination burden that typically falls on one family member."},
  "SR006:Alike": {"founded":2025,"overview":"Alike builds a shared memory layer for AI coding agents, letting tools like Claude Code, Cursor, and Codex share context across sessions. Without it, each agent starts from scratch: redoing rejected work, colliding on the same files, and losing decisions the moment a terminal closes. Alike replaces the developer acting as a manual context router between agents."},
  "SR006:Amdahl": {"founded":2025,"overview":"Amdahl builds a context layer for B2B go-to-market teams, sitting between raw sales, support, and customer success data and the AI agents that act on it. It structures messy GTM data into cited, deal-grounded context so agents writing outreach, researching prospects, or diagnosing pipeline can produce outputs checked against what real buyers said and did. It replaces ad-hoc data wrangling, manual win/loss review, and ungrounded AI drafts that teams currently can't trust before they send."},
  "SR006:Antihero Studios": {"founded":2024,"overview":"Antihero Studios builds mobile games designed around social play, starting with MISFITZ, a free-to-play extraction game for iOS and Android. In MISFITZ, 16 players drop into a shared map, form ad-hoc alliances to loot, and choose whether to extract together or betray each other at the gate. The studio targets the mass-market mobile audience that currently has no native extraction game, replacing the solo or algorithmically matched experience with one built on emergent social tension."},
  "SR006:August": {"founded":2025,"overview":"August builds AI agents that execute commercial banking work, covering underwriting, servicing, and risk, replacing the manual processes that bank staff run today. The platform accumulates a proprietary context layer as usage grows, making each subsequent task faster and more informed. It targets commercial banks, with deployment already in production at a major institution."},
  "SR006:Auto": {"founded":2025,"overview":"Auto turns photos into Frames, small single-purpose AI apps that act on what the camera sees: counting calories, rating an outfit, identifying a plant, splitting a bill, or logging water. Consumers point their phone at the world and Auto selects the right Frame and runs it, replacing the manual effort of opening separate apps or searching for information. Users can also build their own Frames when an existing one does not cover their need."},
  "SR006:Belong": {"founded":2025,"overview":"Belong builds artist-owned membership programs that turn fan loyalty into a financial relationship. Artists issue memberships tied to real financial infrastructure, so fans who have spent years buying records, attending shows, and streaming releases are recognized and rewarded for that history. The product replaces informal, unmonetized fan devotion with a structured, recurring revenue stream driven by spending fans already do."},
  "SR006:Bilrost": {"founded":2025,"overview":"Bilrost builds AI-native infrastructure for commercial lenders, automating the full credit workflow from document ingestion through underwriting and portfolio monitoring. Its agents pull deal files across email, portals, and cloud storage, reconcile rent rolls, leases, and financials, and populate lender-specific underwriting models, replacing weeks of manual spreading, re-keying, and document chasing. Every output traces back to source documents, giving risk and compliance teams a defensible audit trail."},
  "SR006:Bota": {"founded":2026,"overview":"Bota gives AI agent developers a programmatic way to capture and process real-world, offline conversations, covering in-person meetings and phone calls that cloud-based tools never reach. Developers integrate Bota's API to add offline recording to their products; Bota supplies white-labeled hardware, handles manufacturing, logistics, and support, and delivers transcripts and metadata ready for any AI workflow. It replaces the manual work of wiring together physical recording hardware, operations, and data pipelines for teams building AI agents in sales, healthcare, law, finance, and productivity."},
  "SR006:Cascade": {"founded":2025,"overview":"Cascade builds an AI-powered opportunity and proposal platform for architecture, engineering, and construction firms. It continuously scans government and private-market sources to surface matched RFPs, scores each for fit, and then drafts the proposal, replacing weeks of manual portal-watching and proposal writing. The target customer is AEC firms that currently rely on word of mouth and fragmented portals to find and bid on projects."},
  "SR006:Cedar": {"founded":2025,"overview":"Cedar builds an AI-native professional network that scales employee referrals for fast-growing companies. Its agents conduct short calls with employees to map their trusted relationships, surface high-signal candidates, and build a proprietary graph that grows with every hire. The product replaces the manual, people-heavy referral programs that large companies have historically run at significant cost and headcount."},
  "SR006:Clair Health": {"founded":2025,"overview":"Clair Health builds the first continuous, noninvasive hormone monitor: a wrist wearable that tracks estrogen, progesterone, LH, and PdG in real time without blood draws. It uses a custom multi-modal biosensor array and an in-house female biology model to capture over 130 biomarkers, replacing periodic lab tests and manual cycle tracking. Women use it to manage fertility planning, athletic performance, skin health, mood, and perimenopause transitions."},
  "SR006:Coalition Systems": {"founded":2025,"overview":"Coalition Systems builds a secure operating system for national security coordination, connecting military units, intelligence services, government agencies, and critical infrastructure operators on a single purpose-built platform. It replaces the ad hoc use of Signal, WhatsApp, Telegram, and Google Sheets that defense and security organizations have adopted by default, providing communication, collaboration, and decision-support tools designed for field conditions and classified environments."},
  "SR006:Concorda": {"founded":2025,"overview":"Concorda builds an operating system for litigation teams, handling case research, discovery drafting, and document generation end to end. Litigators use it to run interrogatories, requests for admission, and legal research across every U.S. court, replacing the manual drafting and research work that consumes associate and partner time. It is built by founders who practiced law and wrote the code themselves."},
  "SR006:Crebit": {"founded":2025,"overview":"Crebit solves a core problem in stablecoin-based foreign exchange: blockchain rate quotes expire in ten minutes, which prevents businesses from committing to payments in advance. Crebit built a rate-locking layer that holds stablecoin exchange rates for up to 180 days, giving enterprises the certainty they need to plan and execute cross-border payments. The product replaces the manual workarounds and exposure to rate drift that companies currently absorb when moving money across borders via stablecoins."},
  "SR006:Emanate": {"founded":2026,"overview":"Emanate builds AI agents that run revenue operations for industrial materials companies, handling the work that sales and operations teams do manually: fielding inbound inquiries, generating quotes, tracking account expansion signals, prospecting new accounts, and informing pricing decisions. The product operates continuously across every shift, replacing the patchwork of human-driven workflows that govern how industrial suppliers capture and grow revenue."},
  "SR006:Grove Tax": {"founded":2025,"overview":"Grove Tax builds AI agents that automate the full tax return workflow for tax preparation firms, covering client intake, document collection, data extraction, return preparation, and final delivery. The product targets a profession where preparers spend the majority of their time on administrative work rather than actual tax work, replacing manual document chasing, data entry, and client back-and-forth with autonomous agents. The result is a single platform that lets a preparer move from onboarding a client to delivering a signed return without leaving Grove."},
  "SR006:Hammock": {"founded":2025,"overview":"Hammock builds an AI agent that helps consumers capture HSA and FSA savings on healthcare and wellness spending. The agent scans past purchases to surface eligible expenses users have missed, then generates Letters of Medical Necessity through an integrated physician network to make gym memberships, massage, and recovery products HSA/FSA reimbursable. It replaces manual paperwork and guesswork that cause eligible spending to go unclaimed."},
  "SR006:Heavi": {"founded":2025,"overview":"Heavi builds AI agents that source and order parts for heavy-duty vehicle mechanics and fleet teams, replacing the manual work of calling suppliers, checking fitment across OE and aftermarket catalogs, and chasing backorders. A technician drops in a VIN and a part description, and Heavi searches catalogs, contacts vendors, places the order, and coordinates delivery. The product targets a repair and service market where retiring technicians take hard-won diagnostic and parts knowledge with them, leaving shops slower and vehicles sidelined."},
  "SR006:Hotbox": {"founded":2025,"overview":"Hotbox converts Instagram engagement into direct sales for sellers of high-demand drops: jerseys, trading cards, collectibles, tickets, and limited-edition merchandise. It scans comments, stories, and DMs to identify the highest-intent buyers, enriches them against a seller's ideal customer profile, and completes the transaction inside a DM checkout, replacing manual follow-up and lost post-drop revenue."},
  "SR006:Idilio": {"founded":2025,"overview":"Idilio builds a mobile streaming platform for Spanish and Portuguese-speaking audiences, delivering original serialized microdramas in a vertical, 1-3 minute episode format. The content targets Latin American viewers raised on telenovela storytelling who now consume video on their phones, replacing longer-form TV drama with fast, bingeable episodes written by telenovela veterans. Beyond the consumer app, Idilio is developing AI-driven production tools and proprietary data infrastructure to create and distribute serialized stories at scale."},
  "SR006:Kaaro": {"founded":2026,"overview":"Kaaro builds AI agents for railroad operations, replacing the phone calls, emails, and manual paperwork that still drive day-to-day rail workflows. The product handles tasks like incident reporting, billing, data entry, and shipment tracking, work that today runs on tribal knowledge and fragmented systems. Freight railroads are the customer, and the agents act as a shared operational layer that surfaces real-time status and drives action without human chasing."},
  "SR006:Loops AI": {"founded":2025,"overview":"Loops AI builds an intelligence layer for e-commerce brands that structures and enriches product catalog data so AI agents can act on it across search, virtual try-on, and omnichannel sales. The platform converts shopper intent signals into purchases and cuts return rates by giving every downstream agent a consistent, AI-readable view of the catalog. It replaces manual data preparation and disconnected point tools that brands currently stitch together to run AI-driven commerce."},
  "SR006:Miraka": {"founded":2025,"overview":"Miraka delivers clinician-led cardiac care to patients at home, combining continuous wearable and biometric monitoring with real-time clinical intervention to catch deterioration before it triggers an ER visit or readmission. The product targets post-surgical and high-risk cardiac patients who currently go unmonitored between hospital appointments. It replaces reactive, episodic follow-up care with a persistent care team that adjusts medications and therapies as patient data shifts."},
  "SR006:Mirror Mirror AI": {"founded":2024,"overview":"Mirror Mirror AI operates a marketplace where fashion models license their likeness for AI-generated imagery, and brands book those models to produce lookbooks, e-commerce shots, and campaign visuals in hours rather than weeks. Each image generated under agreed terms earns the model a fee, replacing traditional photoshoots for brands while giving models a compensated, consent-based channel for AI use of their likeness."},
  "SR006:Modaic": {"founded":2025,"overview":"Modaic builds verification and alignment infrastructure for AI decision-making. For teams running classification, moderation, or automated evaluation workflows, it scores model confidence on each decision, routes uncertain cases to human reviewers, and uses that feedback to refine the underlying instructions over time. This replaces the binary choice between costly full human review and brittle automated pipelines that fail on edge cases."},
  "SR006:Modern Industrials": {"founded":2025,"overview":"Modern Industrials builds custom AI systems for building materials distributors, automating the back-office work that sales and operations teams handle manually today. Its first product targets inside sales workflows: quoting, order entry, and analytics that currently run on slow, error-prone manual processes. The longer-term goal is a full operating system for physical-goods distribution."},
  "SR006:Oasis": {"founded":2026,"overview":"Oasis builds a hybrid workspace where human teams and AI agents collaborate in shared rooms, documents, and codebases. It targets non-technical teams who want to run multi-agent workflows without writing the underlying infrastructure themselves. The platform maintains a persistent memory layer across every task and decision, so agents carry full context when swapped or upgraded, replacing the manual handoff work that otherwise falls on people each time a model or workflow changes."},
  "SR006:Oasiz": {"founded":2025,"overview":"Oasiz builds a social distribution platform for AI-native software, starting with games. It treats playable software as a content format, giving creators a feed-based arcade where users discover and play AI-built games the way they scroll short-form video. The platform replaces traditional app store distribution for a new generation of creators who generate games with AI tools rather than conventional development pipelines."},
  "SR006:Omi Health": {"founded":2025,"overview":"Omi Health builds a longevity platform for dogs, giving pet owners proactive health data instead of waiting for illness to appear. A blood draw and saliva test measure 80-plus biomarkers and detect more than 1,000 conditions; an AI layer then produces a personalized care protocol for each dog. The product replaces the standard reactive veterinary checkup with continuous, preventive monitoring."},
  "SR006:Panorama": {"founded":2024,"overview":"Panorama builds AI systems for enterprises, ingesting workplace data from Slack, email, and documents to map how teams actually work and surface personalized recommendations for AI adoption. The product delivers those recommendations through a feed-style interface, driving adoption from individual contributors upward rather than through top-down mandates. It replaces manual discovery of workflow inefficiencies and the guesswork of AI rollout planning."},
  "SR006:PartyHat": {"founded":2025,"overview":"PartyHat builds AI-powered tools for interactive party and social experiences. It targets hosts and event organizers, automating game facilitation and activity planning."},
  "SR006:PayPath": {"founded":2025,"overview":"PayPath builds an AI operating system for debt management, replacing spreadsheets, manual workflows, and legacy software across the full credit lifecycle. Enterprise lenders and servicers use its autonomous agents to handle origination, servicing, collections, and recovery. The platform automates the account-level work that previously required large manual operations teams."},
  "SR006:PicPet": {"founded":2025,"overview":"PicPet builds a social messaging app that turns photo sharing between friends into a virtual pet care loop: every photo a user sends feeds their shared pet, making the friendship itself the gameplay. It targets consumer social and creator audiences, replacing passive group chats and static photo-sharing with an ongoing, pet-driven ritual that gives friends a shared object to tend together."},
  "SR006:Piper-ai": {"founded":2025,"overview":"Piper-ai builds an AI operating system for preconstruction that general contractor estimating teams use to manage drawings, specs, addenda, subcontractor quotes, and schedules in a single connected project context. It generates scope documents, bid leveling sheets, estimates, and final bid reviews in the contractor's own formats, with every finding linked to its source document. The product replaces the manual work of assembling and reconciling preconstruction information across scattered files, freeing senior staff from reviewing every package by hand."},
  "SR006:Pluvo": {"founded":2025,"overview":"Pluvo builds an agentic operating system for corporate finance teams, replacing manual spreadsheet work and fragmented reporting with AI agents that run analysis, reconciliations, forecasting, and close tasks end to end. Finance teams connect their existing systems into a single governed context, then delegate recurring workflows to agents whose outputs trace every number back to its source data and calculations. The platform is model-agnostic, so teams are not tied to a single AI provider."},
  "SR006:Prior Foundry": {"founded":2026,"overview":"Prior Foundry builds a decision intelligence platform for government policy and program teams. It combines data connections, scenario modeling, and stakeholder input to track how programs are implemented, where performance falls short, and whether outcomes are being achieved. The platform replaces fragmented, periodic analyses with continuous, real-time evidence that feeds directly into policy decisions."},
  "SR006:Quanto": {"founded":2024,"overview":"Quanto builds an AI-driven sales and operations layer for accounting firms, handling client prospecting, qualification, and calendar booking, then automating onboarding into QuickBooks and cleaning up new clients' books to the firm's standards. It replaces the patchwork of manual outreach, referral dependence, and ad-hoc onboarding that keeps most firms from growing without adding staff."},
  "SR006:Quinn": {"founded":2025,"overview":"Quinn builds AI-powered training and operational readiness software for field service companies, covering trades like HVAC, pest control, roofing, and facilities maintenance. It converts a company's SOPs and top performers' knowledge into structured training that the entire workforce completes, replacing human-led training programs. New hires onboard faster, veterans stay consistent, and crews get instant answers by text while on the job."},
  "SR006:Quo Labs": {"founded":2025,"overview":"Quo Labs builds Sam, a physical voice companion robot for older adults living at home. Sam conducts daily check-in conversations with seniors, then relays updates to their families, replacing the ad-hoc calls and in-person visits families rely on to monitor a loved one's wellbeing. The product targets the gap between full-time caregiving and no oversight at all."},
  "SR006:SafeWorld": {"founded":2025,"overview":"SafeWorld builds a safety testing and evaluation platform for robots operating around people. It generates rare, high-risk scenarios in simulation to surface failure modes that physical testing misses, covering edge cases introduced by human behavior, environmental change, and software updates. Robotics teams use it to assess and document risk before and during deployment, replacing slow, expensive, and unscalable real-world test runs."},
  "SR006:Sellara": {"founded":2025,"overview":"Sellara develops AI models for financial institutions that automate operational workflows and flag issues for human review. The system works inside existing tools and covers middle and back office tasks."},
  "SR006:Sentra": {"founded":2025,"overview":"Sentra builds a managed organizational memory layer for enterprises, ingesting meetings, messages, emails, documents, code, and deal activity from over 200 tools into a single, permissioned context store. It replaces the manual effort of hunting across siloed systems by giving employees and AI agents a real-time, connected record of decisions, commitments, and context as work unfolds. The result is less coordination overhead and fewer hallucinations when agents reason across company knowledge."},
  "SR006:Simula": {"founded":2025,"overview":"Simula builds native ad infrastructure for AI apps, replacing standard banner and interstitial formats with interactive experiences, such as AI brand ambassadors and games played alongside AI companions. AI app developers integrate Simula to monetize their user bases without degrading the conversational or generative experience. The product targets the gap between how conventional ad formats disrupt AI products and what brands need to reach those audiences."},
  "SR006:Sirius": {"founded":2025,"overview":"Sirius builds an AI retention platform for subscription businesses, targeting the early-months churn window that costs consumer companies the most. Its models process subscriber interactions at scale to intervene before cancellation, replacing manual lifecycle campaigns and rule-based retention playbooks. The primary customers are large consumer subscription brands."},
  "SR006:Smart Bricks": {"founded":2024,"overview":"Smart Bricks builds autonomous AI agents for real estate investors, covering the full investment cycle from deal discovery and underwriting through transaction execution and portfolio monitoring. The agents replace manual market scanning, spreadsheet-driven risk modeling, and fragmented diligence workflows that institutional and professional investors run today. Proprietary foundational models trained on real estate data feed multi-step reasoning across more than a thousand variables per opportunity."},
  "SR006:snag": {"founded":2025,"overview":"snag builds an AI-native marketplace for short-term sublets, serving Gen Z renters who currently piece together housing through Facebook groups, Instagram, and Craigslist. Its AI model ingests raw social posts and converts them into structured listings, then matches renters to available sublets within seconds. snag sits between vacation rental platforms and traditional long-term rental sites, making flexible, month-to-month urban housing searchable and transactable in one place."},
  "SR006:Snapp AI": {"founded":2025,"overview":"Snapp AI builds a sports AI assistant that consolidates live scores, news, highlights, analytics, and fantasy lineup decisions into a single app. Sports fans and fantasy players use it to get real-time answers about matchups, injury reports, and waiver wire moves without switching between tabs or apps. It replaces the manual work of aggregating sources, Googling pre-game questions, and guessing at lineup decisions."},
  "SR006:Sparta": {"founded":2025,"overview":"Sparta builds agent testing environments that run AI agents against sealed, simulated replicas of the real systems they operate on, such as Stripe, Zendesk, and Salesforce. Instead of reading conversation transcripts, Sparta grades what actually changed in the system state after each run, giving teams exact, replayable proof of agent behavior. This replaces manual review and transcript-based evaluation with automated, outcome-level verification."},
  "SR006:Straia": {"founded":2025,"overview":"Straia builds an AI-native data platform for college and university administrators, connecting fragmented systems, including student information, learning management, and CRM platforms, into a single environment where staff can query institutional data in plain language. It targets campus leaders across enrollment, academic affairs, and the president's office, replacing manual reporting workflows and disconnected legacy software with AI agents that surface real-time insights on enrollment funnels, retention risk, course outcomes, and financial performance."},
  "SR006:SUN": {"founded":2025,"overview":"SUN generates on-demand podcasts, audiobooks, audio courses, and other spoken audio from a single text prompt, letting listeners customize voice, length, and language. It targets anyone who learns or entertains through audio and replaces the fixed, one-size-fits-all content of traditional podcasts and audiobooks. Users can ask questions mid-playback, clone their own voice, and schedule fresh episodes that arrive automatically."},
  "SR006:Syncere": {"founded":2025,"overview":"Syncere builds Lume, a floor lamp that deploys a pair of robotic arms to handle household chores, starting with laundry folding, then retracts into a standard lamp when the task is done. The product targets homeowners who want chore automation without dedicated robot hardware sitting visibly in their space. It replaces the manual labor of routine domestic tasks and the clutter of purpose-built home robots."},
  "SR006:Taxnova": {"founded":2025,"overview":"Taxnova automates R&D tax credit and CapEx documentation for technology companies, replacing the manual process of engineer interviews and year-end reconstruction. It connects read-only to existing engineering tools, such as Jira, GitHub, Slack, and Confluence, and continuously builds source-linked, audit-ready evidence throughout the year. A tax advisor of the client's choice then reviews and submits the finished claim."},
  "SR006:ThirdBrain Labs": {"founded":2025,"overview":"ThirdBrain Labs builds post-training infrastructure that lets domain teams convert their own expert knowledge into fine-tuned, proprietary AI models they own outright. It captures training signals directly from expert decisions in production, then continuously updates models without requiring large labeled datasets or manual data-preparation work. The product targets teams that currently depend on general-purpose, closed-model APIs and want task-specific models they control."},
  "SR006:Variant": {"founded":2025,"overview":"Variant builds an AI-powered conversion rate optimization engine for consumer brands. Three coordinated agents handle the full CRO workflow: one analyzes shopper behavior and ad context to identify friction points, one designs and codes on-brand A/B experiments for team approval, and one accumulates learnings across tests so each successive recommendation is informed by prior results. The product replaces the manual cycle of dashboard analysis, backlog-dependent development, and disconnected test-by-test iteration."},
  "SR006:Vereda": {"founded":2025,"overview":"Vereda connects Brazilian farmers directly to agricultural input manufacturers, cutting out the distribution intermediaries that compress producer margins. A WhatsApp-native purchasing agent called Vera collects quotes from multiple suppliers simultaneously, structures the buying process from inquiry to payment, and is supported by on-the-ground field consultants who carry existing relationships in their regions. The product replaces a multi-layered reseller chain that adds cost at every step without adding supply."},
  "SR006:Verra": {"founded":2025,"overview":"Verra builds Meridian, an agentic operating system for management consulting firms. It organizes a firm's entire body of work, past engagements, decks, and models, into a single searchable knowledge base, then uses agents to draft proposals and deliverables in the firm's own templates. This replaces the manual work of hunting for precedents, rebuilding from scratch, and losing institutional knowledge when staff turn over."},
  "SR006:ZeroDrift": {"founded":2026,"overview":"ZeroDrift builds a compliance enforcement runtime that intercepts AI-generated communications before they are sent, validating, rewriting, or blocking each message against pre-loaded regulations and company-specific policies. It serves regulated enterprises in financial services, insurance, and healthcare, replacing manual compliance review and ad-hoc output filtering with a real-time, audit-ready enforcement layer. The runtime operates across AI agents, copilots, and any LLM via a single API call."},
  "SR007:Abliteration.ai": {"founded":2026,"overview":"We give offensive security professionals access to models they use to model bad actors that other providers block. We have crossed $7 million in run rate and have been featured in publications like TechCrunch, Wired, and Gizmodo. Our founders previously built inference and GPU platforms at Apple and Microsoft.","founderDetails":{"Devon Thomas":{"role":"Cofounder & CEO","bio":"Let's grow."},"Jide Ogun":{"role":"Co-Founder & CTO"}}},
  "SR007:Acaysia": {"founded":2026,"overview":"Our software sits on top of the controls a plant already has and runs it better. Tens of thousands of plants today run on operator intuition and give up a few percent of everything they make, which is millions of dollars in value. With Acaysia, the plant makes more for less cost, out of the same system.","founderDetails":{"Achraf Zemzami":{"role":"CTO","bio":"Ex-Audible. Amazon AWS offer at 17. Studied CS/Physics at Harvard before leaving.\nL44: Worked on control systems since 6th grade."},"Aias Tatsis":{"role":"Chief of Engineering","bio":"Electrical Engineering at Harvard. Owns Acaysia's physics engine and all of its GPU work: 127+ validated process models, a 3D LBM solver, and the sampling controller on top. Built the company's bench-scale pilot plant by hand."},"Andy Xian":{"role":"Co-Founder & CEO","bio":"Ex-statistics at Harvard. Interned at Balyasny Asset Management. Gates Scholar and Milken Scholar out of Stuyvesant, global finalist in international investment competitions, and nationals qualifier in the Young Physicists' World Cup. Junior Olympics fencer."}}},
  "SR007:AgentCat": {"founded":2025,"overview":"AgentCat is an analytics and observability platform for MCP servers, Claude Connectors, and ChatGPT Apps. With just one line of code using our open-source SDK, you can start getting rich analytics on AI agents and how they're using your product, including features such as session replay, agent goals, issue detection, and more.","founderDetails":{"Kashish Hora":{"role":"Cofounder","bio":"Cofounder of AgentCat, helping teams understand how agents are using their products. Previously led AI B2B at Grammarly/Superhuman."},"Naseem Alnaji":{"role":"Cofounder","bio":"Cofounder of AgentCat, product analytics for MCPs & Claude Connectors Previously founded and exited Opal Security"}}},
  "SR007:Alia": {"founded":2025,"overview":"Alia is building AI agents that coordinate teams toward company goals. As AI has exponentially increased individual productivity and output, coordination is now the bottleneck. Alia connects context across tools and teams, spots misalignment and blockers, and brings the right people and information together to move work forward. In just three months, Alia reached $115k in live ARR, with customers including a food delivery platform processing over 100 million orders a month. Usage among existing users is doubling week on week. Alia is co-founded by Thomas and Livia. Thomas built his first startup at 14 and attended Georgia Tech on a scholarship described as LATAM’s Thiel Fellowship.","founderDetails":{"Livia Kuga":{"role":"Co-founder","bio":"Scaled Stone from founding team to 15.000 people. My job was to keep teams coordinated as we grew from a small team to hiring over 700 people per month and IPO."},"Thomas Filshill":{"role":"CEO","bio":"I built my first startup at fourteen, and attended Georgia Tech on a scholarship described as LATAM’s Thiel Fellowship. Before Alia, I scaled AI systems to hundreds of thousands of users."}}},
  "SR007:Alven": {"founded":2025,"overview":"Alven is an AI employee that replaces human property managers. It connects to your existing software in 3 minutes, then runs the full tenant lifecycle (move-ins, maintenance, move-outs) and back office accounting. We reached $1.2M ARR in 6 months with large real estate funds (Keller Williams, Balgore Group) Deploying right now $10M ARR across large RE funds (70k+ units)","founderDetails":{"Andrey Dobrov":{"role":"Founder & CRO","bio":"Applied Mathematics Graduate & Pro Rock Climber (V11 outdoors). Previously I signed multimillion ACVs at Copper.co (Series C startup)"},"Christian Brown":{"role":"Co-founder & CPO","bio":"Theoretical physics graduate from UCL. I co-published research on neutrino detection with my professor, who has since joined DeepMind."},"Julio-Cezar Scerbina":{"role":"Co-founder & CEO","bio":"Chess pro player at 12 (2100 ELO). #1 Ranked Math Olympian in Republic of Moldova"}}},
  "SR007:Athena": {"founded":2026,"overview":"Athena is an AI-native law firm for repeat M&A and commercial real estate dealmakers. Our founding team brings together 4 early Legora team members and 2 experienced BigLaw partners. We built our own technology to execute transactions at fixed fees, so faster delivery directly improves our margins. The platform is already live on client work. In our first five weeks, we secured 16 account relationships across signed engagements and design partnerships, with approximately $700,000 in committed legal fees.","founderDetails":{"Cem Ucan":{"role":"Co-Founder, CEO","bio":"ex-Legora founding legal engineer. Helped scale Legora to its first $100M ARR, closing and owning many of the largest enterprise accounts (Cleary, Goodwin, Linklaters, Norton Rose Fulbright). Former Baker McKenzie attorney and legal tech lead."},"Kieran John Keenan":{"role":"Co-founder & CTO","bio":"ex-Legora founding evals engineer and member of technical staff.\nL44: Built and scaled Legora’s evaluation function end to end, working across engineering teams to develop the eval infrastructure, operations, and systems underpinning every AI feature, from drafting and research to agentic workflows. Partnered closely with frontier model providers o"}}},
  "SR007:Banbury Road": {"founded":2026,"overview":"Every model since ChatGPT rides the same scaling law: add parameters, and capabilities improve reliably. Banbury Road trains more models instead, delivering frontier capability at a fraction of the cost and memory of big, monolithic SOTA models. The team met as top of the class undergrads at Oxford. Before leaving PhDs at Yale and UChicago, they automated PhDs by shipping freephdlabor, the first AI system to mass-produce peer-reviewed research published at ICLR 2025.","founderDetails":{"Cat Yan":{"role":"Co-founder","bio":"Prev. Oxford, youngest admit in college history for Maths & Stats"},"Ed Li":{"role":"Co-founder & CEO","bio":"Yale PhD. Oxford Maths & Philosophy, ranked 2nd in year, wrote a thesis on lucid dreaming"},"Junyu Ren":{"role":"Co-founder","bio":"UChicago PhD. Oxford Maths & Philosophy, winner of the Gibbs Mathematics Prize (ranked 1st in year)"}}},
  "SR007:Baro": {"founded":2026,"overview":"Baro is the AI General Manager that runs operations and growth end-to-end for consumer brands. Consumer brands spend $185B annually on agencies and outsourced services spanning marketing, logistics, compliance, finance, and customer support. Baro serves all of these functions through a single platform, boosting brands profitability by 50%+. BARO sees the whole business, recommends actions tied to the brand's goals and then executes. Baro enables brands to run leaner, grow faster, and reach the right retailers.","founderDetails":{"Brian Cho":{"role":"Co-Founder & CEO","bio":"3x Founder. Scaled my last startup to a $5M run rate in 18 months and tripled my business unit at Flock Safety. Now I’m building Baro, an AI general manager for consumer brands."},"Max Cummings":{"role":"Co-Founder and COO","bio":"Building the future of commerce. Ex-Google (Shopping Ads), Ex-McKinsey (Consumer and Tech). Most recently was Interim CEO at a 100-person General Catalyst-backed company that built a business-in-a-box for doctors."}}},
  "SR007:Blueprint": {"founded":2026,"overview":"Scouring datasheets, hunting for components, or sketching wiring diagrams is all heavy lifting before any building actually starts. While software has gotten easier to make, hardware still remains bottlenecked by traditional design principles. Our goal is to deliver the first language to hardware prototype platform that turns high-level requirements into complete hardware designs. What currently takes engineering teams’ entire weeks of conceptualizing now takes minutes. We aren’t just building a tool; we’re building the infrastructure for the next generation of physical products.","founderDetails":{"David Feldt":{"role":"CEO","bio":"Making hardware go faster"},"Pranav Seelam":{"role":"CTO","bio":"Turning plain language into physical machines."},"Sajeel Purewal":{"role":"COO","bio":"Hardware as fast as thought"}}},
  "SR007:Bounty": {"founded":2026,"overview":"Bounty lets founders and small businesses hire AI agents and specialised teams for work ranging from lead generation and research to content and launch videos. Customers delegate one-off projects or recurring work instead of managing the tools themselves. On individual tasks, customers fund the deliverable upfront, with payment released after verification against agreed requirements and buyer review. Bounty reached $1M+ in annualized GMV in September and is on track for $1.5M+ in annualized GMV in October. It has secured more than $15K per month in recurring customer commitments from 15 businesses, and onboarded 200+ third-party agents.","founderDetails":{"Aashna Doshi":{"role":"CEO","bio":"I’m Aashna, Co-founder & CEO at Bounty, a former Google software engineer in AI and security, and a Georgia Tech Master’s graduate in Machine Learning. Growing up across three countries: Belgium, India and the US shaped my global perspective on technology, culture, and business. I combine deep technical expertise with a strength in distribution: I’"},"Shivam Patel":{"role":"CTO","bio":"I’m Shivam, Co-founder & CTO at Bounty. I grew up in New Jersey, studied ECE at Rutgers with a minor in Computer Science, and also studied at Georgia Tech. Before Bounty, I worked on the algo trading team at Barclays and helped build the hardware and software for skill game machines at a company that scaled from $0 to $2M in sales in 2 years.\nL43: "}}},
  "SR007:Bric": {"founded":2026,"overview":"Founding Team • Sohom: Former Director of Product at Slack. Founding member of Slack AI, which he scaled from 0 to $100M+ in ARR. • Ashwin: Built ML models for multifamily housing at CoStar. Led AI systems at Snap handling $120M+ in ad spend. • Austin: 9+ years at NASA, Amazon, and Snap. Staff Engineer and Engineering Manager leading 30+ engineers on core infra serving 400M+ daily users. TEDxUCLA speaker. Featured on NBC's Today Show.","founderDetails":{"Ashwin Ayyasamy":{"role":"Co-Founder","bio":"Built ML models for multifamily housing at CoStar. Then led AI systems at Snap that handled $120M+ in advertising spend."},"Austin Vaday":{"role":"Co-Founder","bio":"9+ yrs at NASA, Amazon, and Snap; staff Software Engineer and EM leading 30+ eng orgs on critical infra for 400M+ DAUs. TEDxUCLA speaker; NBC Today Show feature."},"Sohom Paul":{"role":"Co-Founder, CEO","bio":"Former Director of Product at Slack. Founding member of Slack AI, which I scaled from 0 to $100M+ in revenue."}}},
  "SR007:Cartsy": {"founded":2025,"overview":"Cartsy is building the agentic commerce layer for social media, targeting the growing $120B social commerce market. The company leverages multimodal LLMs and a proprietary product matching engine to turn content into a shoppable experience in seconds. This can take the form of a creator’s link-in-bio storefront or an AI shopping agent that users can access directly inside Instagram or TikTok.","founderDetails":{"Alain Michel":{"role":"CEO","bio":"Graduated from Duke University, Economics (NCAA D1 Tennis) - Founder of Mundo Pet, exited to Cobasi (BVMF: AUAU3) - Co-founder at Lastro - $15m Series A - Partner & COO at BR Media - Acquired by Publicis Groupe (EPA: PUB) Personal Interests: Sports, Food, Retail and Media"},"Raul Dagir":{"role":"Founder & CPO"}}},
  "SR007:ChatOverflow": {"founded":2026,"overview":"ChatOverflow is the platform where agents all over the world can truly communicate and make each other better. As agents take on increasingly important and complex tasks, they get stuck on time-consuming problems like tool errors, UI navigation, or just bad product taste. They ultimately solve them through repeated trial-and-error or human intervention. Along the way, they find fixes, discover patterns, make decisions, and develop judgment. But that knowledge remains isolated to a single agent. ChatOverflow lets agents share what they learn, search what others have already figured out, and build on the best answers instead of repeating the same work.","founderDetails":{"Ansh Tulsyan":{"role":"CoFounder","bio":"Prev built AI tools for chip design used by thousands of engineers at AMD"},"Ishaan Chamoli":{"role":"Co-Founder","bio":"Prev AI @ Boardy, AMD / CS @ UIUC"}}},
  "SR007:ChronoSpace": {"founded":2025,"overview":"Physical industries like manufacturing, retail, and construction are missing out on billions in productivity gains because AI is stuck in 2D. They process pixels, but don’t understand the 3D world – or how it changes over time. At ChronoSpace, we build 4D (3D + time) world models that digitize and simulate the physical world, unlocking greater efficiency and automation in physical industries. Imagine digital twins of factory floors that help increase throughput, or digital replicas of the real world to train robots faster – ChronoSpace’s world models make this a reality.","founderDetails":{"Aashish Rai":{"role":"Co-Founder","bio":"Aashish leads spatial AI development and engineering at ChronoSpace. He is also a PhD candidate at Brown and an expert on building spatial AI models (e.g., PackUV, UVGS). He was previously at Meta and CMU, and has spent the last several years inventing state-of-the-art 3D/4D reconstruction algorithms.\nL46: He has published at top-tier research venu"},"Srinath Sridhar":{"role":"Co-founder & CEO","bio":"Srinath is co-founder and CEO at ChronoSpace, and a professor at Brown. His expertise is in building spatial AI models for the physical world that go beyond the current generation of AI. He is the director of Brown IVL, one of the leading spatial/physical AI research groups in the world.\nL45: He is the recipient of a Google Research Scholar award, "},"Tamar Kreitman":{"role":"Co-Founder and Capture Systems Development","bio":"Tamar leads capture systems development at ChronoSpace. Her expertise is in all things hardware, with a background in embedded systems and circuit design. She has designed wireless data capture systems across a wide range of applications."}}},
  "SR007:Cluster": {"founded":2026,"overview":"We've hit $260k+ ARR in our first 11 weeks, growing >100% MoM. AI-native startups plug our MCP into their agents to consolidate multiple GTM tools into one platform they operate from Claude/Codex. Our MCP is optimized with unique agentic usage data and benchmarks show we outperform competitors: sales agents complete tasks 30% faster, 4x cheaper, and more accurately using Cluster vs others. Through this new approach, customers have unlocked millions in incremental qualified sales pipeline. Luis studied data science at MIT, published award-winning experimentation research, and scaled production ML systems to 10 million users at Remitly.","founderDetails":{"Enrique Goudet":{"role":"Co-founder","bio":"- Built terabyte-scale data pipelines used by Bloomberg, Home Depot, the Department of War, and the US Air Force. - Serial hackathon winner (e.g.\nL41: $50k prize at Solana worldwide competition) - First engineering hire at PeakMetrics (Series A startup) - Undergrad CS & Math @ Occidental College"},"Luis Costa Laveron":{"role":"Co-founder & CEO","bio":"- MIT data science, Caltech and Edinburgh CS - Built ML models for 10 million users at Remitly, top 5% performer - Published award-winning operations research (MIT ORC & ABInBev)"}}},
  "SR007:Codos": {"founded":2026,"overview":"Codos helps public and PE-backed companies to achieve P&L impact from AI months ahead of schedule. 7-digit live ARR, repeat founders pairing Meta and Tesla machine learning (the brains) with McKinsey implementation (the hands) turning a $500BN AI-services industry into software. Codos runs AI agents that interview the entire workforce and identify inefficiencies, operates a virtual Chief AI Officer that automates sales, operations and engineering workflows, and deploys the benchmark-winning company brain. Successfully delivered $10M+ of impact to NASDAQ-listed and private clients. 1.6M views on X launch video and multi-million customer pipeline.","founderDetails":{"Dima Khanarin":{"role":"CEO","bio":"Prev. McKinsey, Everclear ($30M+ raised). Spent last 10 years doing building and transforming organizations as a consultant and founder - now automating this process and helping create self-improving organizations."},"Gleb Sidora":{"role":"CTO @ codos.ai"}}},
  "SR007:Coherence Health": {"founded":2026,"overview":"We're building an AI functional medicine doctor - using AI to replicate the reasoning of elite functional medicine clinicians at a fraction of the cost. Our first patients are the 1/6 American women with debilitating symptoms due to connected underlying conditions (thyroid, gut, immune). Founder Kush Sharma studied CS at Harvard, holds multiple CRISPR gene therapy patents, and bootstrapped his first healthcare company to $700k in annualized revenue in under a year. Cofounder Patrick Hanaway, MD, founded the Cleveland Clinic Center for Functional Medicine and was the CMO at Genova Diagnostics through a $250M exit.","founderDetails":{"Kush Sharma":{"role":"CEO","bio":"Harvard CS, programming since 14, hold multiple CRISPR gene therapy patents, and bootstrapped my first healthcare company to $700k annualized in under a year."},"Patrick Hanaway":{"role":"MD","bio":"Pioneer in Functional Medicine. Co-founded the Cleveland Clinic Center for Functional Medicine and was the CMO at Genova Diagnostics through a $250M exit."}}},
  "SR007:Colmez": {"founded":2026,"overview":"Colmez is the agentic platform for America's $248bn hazardous waste industry, which runs on phone calls, spreadsheets, and handwritten notes. Teams use Colmez to connect regulatory, commercial, and operational data and automate how waste is treated and disposed. Since opening private beta on Sept 14, Colmez has $800k+ in contracted ARR as a team of 3. Five of the top seven operators use Colmez, including the largest. Rayhan and Brian traded the very companies they now call customers as SIG quants. Numair operated them at PE firms Antin and Ares. We developed personal relationships in our industry through our former jobs. Currently in a16z Speedrun.","founderDetails":{"Brian Meng":{"role":"Co-Founder & CTO","bio":"Berkeley Math and CS '26. As a quant trader at SIG and OMC, he traded the companies Colmez now calls customers. AI researcher at BAIR Labs. Quantum physics researcher at Boeing. Turned down a full-time IMC quant offer to build Colmez."},"Numair Razzak":{"role":"Co-founder & COO","bio":"Stanford Economics '25. As a private equity analyst at Antin Infrastructure and Ares Management, he operated the companies Colmez now calls customers.\nL43: Investment banker at Nomura Greentech."},"Rayhan Razzak":{"role":"Co-Founder & CEO","bio":"Stanford Math '26. As a quant trader at SIG and Peak6, he traded the companies Colmez now calls customers. AI researcher at Stanford's Nguyen Lab. Turned down a full-time IMC quant offer to build Colmez."}}},
  "SR007:Contxt": {"founded":2026,"overview":"We believe the next big shift in work isn't the model or the agent. It's the interface. General-purpose AI agents (Muse, Instinct, etc.) are supercharging how consumers get things done. But employees still spend 60% of their time on work about work, and switch between apps 1,200 times a day. We give a team's tools, people, and history one model-agnostic memory and action layer. In seconds, anyone can turn a single sentence into finished work across their entire stack. Contxt works in Slack, Teams, Claude, ChatGPT, everywhere work happens. You get the ease and speed of a consumer AI assistant, with the controls, audit trail, and dynamic shared memory a company needs.","founderDetails":{"Samiksha Gaherwar":{"role":"CEO","bio":"Samiksha Gaherwar — Recruited by NASA at 16 to lead published research on enterprise knowledge management, where she worked full time for years while graduating valedictorian on the side. Previously exited in the legaltech space, while working in quant research, ML research, and investment banking at F500s. Graduated from Princeton this May with an"}}},
  "SR007:Coop": {"founded":2026,"overview":"Coop builds independent, industry-specific benchmarks so robotics teams can validate their models before they ship. Every task runs on real robots under a fixed setup, and we report results by robot, model, and task, so scores are directly comparable across model developers. We have published our benchmark results, are working with six top academic robotics labs including MIT CSAIL, Stanford SAIL, and Penn Engineering's GRASP Lab, and built over $225K in pipeline in under a month. We also open-sourced the first high-level motor controller built for the Unitree R1.","founderDetails":{"Adithiya Balaguru":{"role":"Co-Founder & COO"},"Arnav Bhalla":{"role":"Co-Founder & CEO","bio":"Prev. Motif Neurotech & Rice BCI Lab. Left Rice Bioengineering to build Coop. TJHSST alum."},"Rohith Yelisetty":{"role":"Co-Founder & CTO"}}},
  "SR007:Corlen": {"founded":2026,"overview":"We move loans from intake to underwriting with no manual work. Just 6 weeks after starting the company, we signed our first pilot. Waruna (CEO) closed dozens of real estate deals while building product at Meta and Linkedin. Meheresh (CTO) led Platform AI at Rippling, building the agentic systems behind Rippling AI, one of its fastest-growing products.","founderDetails":{"Meheresh Yeditha":{"role":"Co-Founder & CTO","bio":"Staff Engineer + Tech Lead Manager at Rippling for 4.5 years. Built and led the foundations of Rippling’s AI platform and product strategy.\nL42: Technical lead for three Tier 1 launches: Devices Agent, Rippling AI, and Data Cloud. I’m a CMU graduate and completed a master’s degree and thesis in Computational Linguistics at the University of Washing"},"Waruna Yapa":{"role":"CEO","bio":"Spent ~6 years at Meta, Linkedin, and Microsoft working on databases, systems telemetry & graph databases. While working, started a Real Estate Investing firm and did ~30 deals. If you want to talk about real estate, finance, or coffee + latte art, hit me up!"}}},
  "SR007:Cube Computer": {"founded":2026,"overview":"Cube Computer provides powerful, one-click cloud dev boxes that ship with a clean and extensible interface. Our ICP is agent-piled developers running intensive agent workloads that need persistence and performance. We launched five weeks ago, have +400 users, 56% compounded WoW WAU growth, and have started monetizing. Yiliu Shen-Burke (CEO) is ex-Harvard and previously built Spaceframe, a mini-visionOS for the Meta Quest. Paul Rony (CPO) built an IPFS-backed AI research tool called Kosmik and raised $10M, including from Creandum. Our VM infra engineer Saúl built the fastest VM hypervisor and is a national crypto hackathon winner in Spain.","founderDetails":{"Paul Rony":{"role":"Co-founder","bio":"Before working on cube I was the founder of Kosmik, an IPFS-backed spatial canvas for creative teams with a built-in browser and AI asset search. Kosmik raised $10mm over eight years, including a $4mm seed led by Creandum, and scaled to 100k users.\nL53: I studied philosophy at the Catholic University of Paris and the Sorbonne, which I left to start"},"Yiliu Shen-Burke":{"role":"Founder","bio":"Harvard architecture dropout, previously built mini-visionOS for Meta Quest. Founder @ Cube Computer."}}},
  "SR007:Cybernetic Physics": {"founded":2026,"overview":"Cybernetic Physics deploys autonomous robots inside data centers. We deploy third-party humanoids and mobile manipulators to handle rack and stack, cabling, and maintenance 24/7. Since launching 8 weeks ago, we've scaled to $828k live ARR and won a contract from DeepAI to deploy more than 10 robots to build and operate a lights-out data center in San Francisco. Co-founder and CEO Natalia was previously at Stanford's Scaling Intelligence Lab and met her co-founder and CTO Luc while working on confidential compute at Lucid Computing.","founderDetails":{"Luc Chartier":{"role":"CTO"},"Natalia Kokoromyti":{"role":"CEO","bio":"Co-founder and CEO of Cybernetic Physics, which deploys autonomous robots to operate data centers. Previously a researcher at Stanford's Scaling Intelligence Lab working on self-improving, scalable ML systems + Lucid Computing working on confidential compute."}}},
  "SR007:Delightful AI": {"founded":2026,"overview":"Delightful AI builds post-training infrastructure like reinforcement learning environments to solve the hardest problems in science and healthcare.","founderDetails":{"Harshel Bahl":{"role":"Co-founder","bio":"(ex Scale ai, Bespoke Labs), projected >1M ARR in one month."}}},
  "SR007:DRS": {"founded":2025,"overview":"DRS is an AI-native consumer app studio that builds and operates high-quality products on a shared backend and live-ops foundation. Our stack covers marketing, data, content management, A/B testing, pricing, and user identity. Each new app builds on existing infrastructure, while successful features and learnings can be applied across the portfolio. As AI makes development easier, we focus on the harder challenge: acquiring, converting, and retaining users. We have launched three apps and reached $1.3M ARR. Second app reached $400K ARR in 30 days, versus 220 days for our first app.","founderDetails":{"Ahmet Onur":{"role":"Co-Founder","bio":"Ahmet is the co-founder of DRS, an AI-native consumer app studio combining consumer research, product development, and growth expertise to build AI-powered consumer products. He serves as Board Member and Capital Strategy Lead, responsible for strategy, senior hiring, partnerships, and fundraising.\nL53: DRS joined a16z speedrun's SR007 cohort in Sa"},"Osman Elsoz":{"role":"Co-Founder / CEO","bio":"Osman is the co-founder of DRS, an AI-native consumer app studio combining consumer research, product development, and growth expertise to build AI-powered consumer products. DRS joined a16z speedrun’s SR007 cohort in San Francisco. Previously, Osman led data at Alictus/SciPlay, working on games with 500 million combined installs.\nL47: He built dat"},"Talha Alver":{"role":"Co-Founder","bio":"Talha is the co-founder of DRS, an AI-native consumer app studio combining consumer insight, product development, and growth expertise to build AI-powered consumer products.\nL50: He focuses on growth, monetization, and distribution, bringing these disciplines into the product development process from day one. DRS joined a16z speedrun’s SR007 cohort"}}},
  "SR007:Elu": {"founded":2026,"overview":"ELU is the intelligence layer for self-improving software: it finds what's breaking for real users, writes the fix, verifies it with code review and simulated users, then merges it. It's built for teams shipping at AI speed, including companies that can't send user session data to third party tools, since ELU runs on their own infrastructure with our licensed models. We've done 8x growth in ARR in under two months, 600+ companies onboarded since launch, and more than $2M in pipeline including Google and Cisco, with a team out of Microsoft Copilot, Stanford and Berkeley.","founderDetails":{"Ali Ajam":{"role":"CTO"},"Sorhan Karimloo":{"role":"CEO"}}},
  "SR007:Embrasure": {"founded":2026,"overview":"Data warehouses weren't built for the AI era. We are providing companies with an all-in-one data warehouse that is agent native, cost efficient, and can effectively handle exabyte scale.","founderDetails":{"Jacob Kieser":{"role":"Co-CEO","bio":"Co-Founder of Embrasure - building the future of a fully autonomous data warehouse. Previously led AI & Data initiatives @ Palantir and Uber."},"Victor Sunderland":{"role":"Co-CEO","bio":"Co-Founder of Embrasure - building the future of a fully autonomous data warehouse. Previously led data + compute work @ OpenAI."}}},
  "SR007:Fictional": {"founded":2025,"overview":"Fictional is a consumer app where people discover, follow, and build relationships with AI characters that have lives of their own. Characters have evolving goals and schedules, share their lives through images, video, and voice, and proactively reach out first. Fictional has reached 1.3 million users, with 1.4-hour sessions. Seung Nam and Mikhail Sychev have built for billions, multiple times over. Between them, they led & launched the modern YouTube.com, Waymo in SF, and Android Automotive OS that powers most new cars - and Pony, the leading open character image model (>3B images generated).","founderDetails":{"Mikhail Sychev":{"role":"CTO","bio":"X-Google, TL of modern YouTube rebuild, ex-Waymo Research Staff SWE, Creator of Pony Diffusion (1B+ images generated), National and California TKD champion"},"Seung Nam":{"role":"CEO","bio":"X-Google, YouTube, Android, Microsoft, BCG, Princeton alum. Retired competitive hiphop dancer & choreographer."}}},
  "SR007:Flip": {"founded":2026,"overview":"Flip is a money expert that lives in your messages, continuously monitoring your accounts and finding opportunities for you to save, make, and invest your money. With Flip, our users make better financial decisions, investing more, improving their credit, and even finding deals on their every day purchases. Flip is live with 74,000 users waitlisted, and has over 2,200 users managing $57,000,000 in connected accounts in 2.5 weeks. Our team is made of Berkeley alumni that are obsessed with Personal Finance, including half a decade in fintech experience, years of training in cybersecurity, and exited founders in the consumer agent space.","founderDetails":{"Alex Jiang":{"role":"Founder, CTO","bio":"2x national champion, 5x national 4th place or above in cyber defense competitions. I lead work on the strongest security and guardrails ever on an agentic assistant."},"Oleg Viatkin":{"role":"Founder","bio":"studied math and cs at Berkeley. previously founded a legal tech company backed by pear vc. working on making your money truly autonomous at Flip"},"Sanjay Amirthraj":{"role":"Founder, CEO","bio":"I have dedicated most of my career to making money easy. Previously, I worked heavily in the digital asset space, helping to create the first open-source harness for an LLM to call tools, scaling to $2.7B FDV. I am an alumnus of UC Berkeley, and my code has touched almost seven figures in volume every single day. We started to flip to bring persona"}}},
  "SR007:Galileo Space": {"founded":2025,"overview":"Galileo Space builds satellites that compute in orbit for national security. We fuse RF and optical sensing onboard and downlink actionable intelligence instead of raw data so warfighters act faster. In July 2026, we delivered two live demos of RF classification and optical fusion to Space Force teams. As of September 2026, we have three signed support letters from Space Force and AFRL, six countersigned commercial imagery LOIs, and are developing our first $1.25M Space Force contract. CEO Kazi Farabi led end-to-end on-orbit testing of protected military communications satellites. CTO Tadeh Mirzakhanian led RF hardware for Starship Flights 2–9 at SpaceX.","founderDetails":{"Jose Serrano":{"role":"Co Founder","bio":"My name is Jose and I’m a co-founder for Galileo Space. I’ve been leading the goverment contracts effort as well as the software architecture of our AI satellites. I have experience at Google, Amazon, Northrop, and Lockheed Martin and have been a software engineer for the past decade."},"Kazi Farabi":{"role":"CEO","bio":"My name is Kazi and I'm the CEO and co-founder of Galileo Space. I've spent my career building classified military satellites and missile systems at Northrop Grumman, Lockheed Martin, and Booz Allen Hamilton, where I was a lead systems engineer on protected military communications and missile warning satellites and led on-orbit testing for two of t"},"Tadeh Mirzakhanian":{"role":"CTO - RF Hardware & DSP Engineer","bio":"CTO and cofounder of Galileo Space.\nL45: I led all RF hardware on Starship Flights 2 through 9 at SpaceX, including the first Starlink phased array on Starship. Before that, electronic warfare at Raytheon on the MALD-N jammer."}}},
  "SR007:Harbor AI": {"founded":2026,"overview":"We’re building Harbor to be the operating layer that keeps GPU fleets productive. A fleet can be completely online and still be wasting compute. Training takes longer, or an inference service handles fewer requests than it should. We’re starting with software for AI teams running dedicated GPUs that figures out why workloads are failing or slowing down, makes supported fixes with approval, and checks whether performance recovers. We’re building a context engine that keeps track of the setup, what changed and what worked before, and developing models that use that understanding to predict which changes will help.","founderDetails":{"Param Shah":{"role":"Co-founder and CEO","bio":"Building Harbor to fix the most expensive problem in AI infrastructure. Previously led product at Microsoft AI Supercomputing, managing GPU deployments for frontier AI labs. Ex-Berkeley"},"Sahaj Putcha":{"role":"Co-Founder","bio":"Building Harbor to fix the most expensive problem in AI infrastructure. ex amazon robotics, cs @ uiuc"}}},
  "SR007:Hoid": {"founded":2026,"overview":"Hoid builds software that optimizes AI inference for any model on any hardware. Today, it takes expert engineers weeks to optimize a single model. Oftentimes, by the time they finish, the next hot model is already out. Hoid's agentic AI compiler optimizes a new model in days instead of weeks and automatically beats expert-optimized engines like vLLM and SGLang by 30%. In just one month, Hoid has scaled to a $196K contracted run rate with live customers, and additional advanced pilots are underway with an audio model lab, multiple inference providers, and a large, global autonomous driving company. Hoid was co-founded by a team of AI performance engineers.","founderDetails":{"Momčilo Mrkaić":{"role":"Co-founder & CEO","bio":"Building Hoid - Agentic AI Compiler. prev: SWE @ Databricks ML intern @ Microsoft BsC @ City University of Hong Kong"},"Pavle Padjin":{"role":"CTO","bio":"Building Hoid - Agentic AI Compiler.\nL44: prev: AI Compiler Engineer @ Tenstorrent AI Msc @ University of Cambridge ML intern @ Microsoft"},"Vladimir Zeljkovic":{"role":"Co-Founder","bio":"Building Hoid - Agentic AI Compiler prev: AI Compiler Engineer @ Tenstorrent Machine Learning Researcher Intern @ JOANNEUM RESEARCH BsC @ University of Belgrade"}}},
  "SR007:Infragrid": {"founded":2026,"overview":"Infragrid is building a proactive AI platform that watches how you work across apps and suggests automations. It turns your clicks, navigates, and app logs into code and leverages a memory system to dynamically recommend agents in real time. Users get suggested agents without needing to prompt each time. In just 2 weeks, we've scaled to $302K ARR and are helping hyper-growth companies like Corgi save 70% more time through discovering critical workflow automations.","founderDetails":{"Ashwin Kodibagkar":{"role":"Co-Founder","bio":"Prev @ Mercor, AWS, Microsoft"},"Ephraim Sun":{"role":"Cofounder","bio":"Delta @ Palantir, then FDE @ Poetic (Series a led by Kleiner, Founders Fund). Automations since day 1"}}},
  "SR007:Kairo": {"founded":2026,"overview":"Security testing can’t keep pace with AI-accelerated development and unpredictable agent behavior. Kairo models how people and AI agents interact with each customer’s application. It uses that model to predict attacks, generate mitigations, and run 24/7 simulations in a digital twin, continuously finding security vulnerabilities before changes reach production.","founderDetails":{"Ankit Chandra":{"role":"CTO","bio":"Ex-AWS. Top 5% on HackerOne. NASA Research @ 16. Georgia Tech Cybersecurity Dropout. Grew nonprofit to 65K Members. 1st Place @ Largest Hackathon."},"Siddharth Dhanasekar":{"role":"CEO","bio":"Ex-BCG. Georgia Tech Cybersecurity. Competitive Hacker (since 16 yrs old). Advisor to OpenSea ($12B). Stanford Security Research @ 18. Won 15+ Hackathons."}}},
  "SR007:Keythorn": {"founded":2026,"overview":"Keythorn is insurance for AI agents. We stress test agents, monitor them, and turn what we find into a risk profile. Companies use it to fix their agents and get through procurement. We use it to place AI liability coverage. Backed by a16z speedrun, Okta co-founder Frederic Kerrest, insurance executives, and cybersecurity researchers.","founderDetails":{"Casey Tewey":{"role":"Founder, CEO","bio":"MIT '25. Played varsity baseball, was tech lead at Chromatic, and chaired MIT's entrepreneurship board. Now building infrastructure for emerging AI liabilities."},"Michael Wong":{"role":"CTO","bio":"CS @ MIT. ML Research + Varsity Swimming. Prev raised $2M+ as a YC founder and grew it to $300K ARR. Now building Keythorn!"}}},
  "SR007:KIRA": {"founded":2026,"overview":"KIRA turns industrial wastewater from a liability into clean water and recovered minerals, so water never bottlenecks critical infrastructure. Our modular, software-defined treatment systems drop into mining, oil & gas, and data centers, where water is the #1 cited cause of $64B in stalled projects. Founded by MIT PhDs and hardware engineers who shipped their first commercial system in under three months vs. 2+ year industry timelines. KIRA is already at $900K in contracted ARR with LOIs across these industries.","founderDetails":{"Jon Bessette":{"role":"CEO & Cofounder","bio":"I am Jon Bessette, a mechanical engineer (SUNY Buffalo BS '20) and scientist (MIT PhD '25) by training. I'm an Activate Fellow, National Science Foundation Graduate Research Fellow, SUNY Chancellor's Awardee, and former Fulbright scholar. Currently, I'm working on building KIRA (www.kira.eco): it's our mission to transform industrial wastewater int"},"Shane Pratt":{"role":"CTO"}}},
  "SR007:Lazyweb": {"founded":2026,"overview":"As growth execs at Discord, Duolingo, and Photomath (acq. Google), we watched AI take engineering exponential while product teams fell behind. Now we're reimagining what product growth teams are capable of using AI, scaling 0->$1M live ARR in only 2mo. Join us!","founderDetails":{"Ali Abouelatta":{"role":"Cofounder","bio":"Grew the slope of Duolingo's revenue Doing the same, but for a lot more companies with Lazyweb."},"Francesco Polizzi":{"role":"ceo","bio":"Led growth at Discord and helped build/sell Photomath (AI Tutor) to Google for 500m."},"L":{"role":"ceo at","bio":"azyweb Francesco Polizzi Led growth at Discord and helped build/sell Photomath (AI Tutor) to Google for 500m."}}},
  "SR007:Leonidas": {"founded":2026,"overview":"Europe is entering a defining decade. NATO allies have committed to spend 5% of GDP on defence and security by 2035, unlocking over €1 trillion in spending. This has fueled a wave of innovation far beyond traditional defence: from AI, space and robotics to energy, compute and biotechnology. But traditional financial institutions were never designed to bank or finance the kind of innovation Europe now needs at scale: high-growth, technologically advanced, and operationally complex, often in sensitive areas such as defence and dual-use. Left unaddressed, that mismatch risks becoming the #1 bottleneck to Europe's economic, technological, and strategic future.","founderDetails":{"Markos Fragkiadakis":{"role":"Founder & CEO","bio":"Ex-Goldman Sachs. Led €15B+ in debt syndications for European banks in early 20s. MBA from Harvard Business School."},"M":{"role":"Founder & CEO","bio":"arkos Fragkiadakis Ex-Goldman Sachs. Led €15B+ in debt syndications for European banks in early 20s. MBA from Harvard Business School."}}},
  "SR007:Maestro": {"founded":2026,"overview":"Maestro is an AI-native luxury travel concierge for high-net-worth families. Every subscriber is supported by a human advisor, backed by Conductor, Maestro's AI orchestration system, which absorbs the research, supplier negotiation, itinerary construction and reward points math needed to delivery an extraordinary travel experience. Today over 90% of the multi-trillion-dollar travel market still runs unmanaged. Maestro has reached $3M in revenue in the nine months since launch, still in stealth and with no paid marketing. Maestro was founded by Prahar Shah, an early leadership team member at DoorDash.","founderDetails":{"Prahar Shah":{"role":"Founder & CEO"}}},
  "SR007:Mecone": {"founded":2026,"overview":"The future of finance will be more open and global, with participants of every kind, retail and institutional alike, trading more of the world's assets with less friction than ever before. In this future, Perpetual Futures (\"Perps\") will become the primary tool for speculation and hedging. With this future in mind we're building the financial infrastructure to let anyone trade Perps on any underlying asset. Today, Perps only exist on a handful of asset classes (e.g. the biggest commodities, FX, public equities, crypto). But there are a myriad of highly attractive long tail assets that Perps have failed to reach.","founderDetails":{"Hugo Stack":{"role":"President","bio":"Hi, I'm Hugo! Since 2021, I've graduated college (Wofford College), received an MPhil (Clare College, University of Cambridge), worked on a farm, lived in a car for two and a half months, written a novel, passed the CFA Level 1 exam, started at and dropped out of Stanford Law School, and now I'm here.\nL44: I love reading (mostly classics), going to"},"Jaffar Keikei":{"role":"CTO","bio":"My name if Jaffar. UWaterloo masters, and University of Toronto undergrad. 2 Google internships. 7/15 hackathon wins. Built a remittance app that my friends and I currently use to send money home at no cost."},"Xan Wesley":{"role":"CEO","bio":"CEO & Co-Founder at Mecone. Previously at Stanford Law School and UC Berkeley, where I studied political science and neuroscience. In undergrad, I worked at Emory's Winship Cancer Center identifying gene targets for treating rare pediatric renal cancers. Since high school, I've run a non-profit that raises money for cancer research and connects pat"}}},
  "SR007:Mirai": {"founded":2026,"overview":"Mirai is building the application layer for world models, starting with real estate. Enter any address and Mirai turns the surrounding area into an explorable simulation. Walk the streets, visit nearby places, follow your commute, and experience what daily life there could actually feel like before you ever go. Real estate is our first deployment. The same technology can make a hotel explorable before you book it, a destination before you travel, or a community before it’s built. We’re making the physical world explorable from anywhere. Ex Tiktok, Shopify, Waabi, Walmart Blue Labs.","founderDetails":{"Andrew Shum":{"role":"Co-Founder & CTO"},"Caleb Lo":{"role":"Co-Founder & CEO"},"Joshua Zhang":{"role":"Co-Founder & COO"}}},
  "SR007:Motherboard Labs": {"founded":2026,"overview":"As fleets of robots and autonomous machines scale in the real world, keeping them running becomes an operational challenge in itself. Motherboard Labs is building the full-stack service layer to enable that. Every deployment reflects the machines, systems, service knowledge, rules, and workflows already in place-helping teams diagnose faster, resolve more remotely, and give technicians the right context when field work is needed. Every fix in the field becomes a playbook and feeds back into engineering - improving procedures, driving fleet-wide fixes, and helping build better machines. The founders prev.","founderDetails":{"Pranit Gupta":{"role":"Co-founder","bio":"Prev. led AI deployments in industrials and heavy machinery at Palantir"},"Robert Doherty":{"role":"Cofounder","bio":"Previously led mission-critical infrastructure at Citadel Securities and focused on industrial technology at McKinsey & Co."}}},
  "SR007:Munari": {"founded":2026,"overview":"Munari is quality scoring for robotics data. Our platform processes, annotates, and scores every episode and evaluates operator performance. We then turn those evaluations into actionable feedback, helping teams improve data quality and get more value from every hour of collection. Both cofounders were previously at Hedra (a16z-backed, Series A video model startup). Ramin was also the CTO at StockX (scaling from $0 to $1B+ GMV run rate) and a 3x founder.","founderDetails":{"Alan Guo":{"role":"Co-Founder","bio":"Previously the Head of Business & Chief of Staff at Hedra where he helped scale the company to 8-figure ARR within 6 months. He led GTM, operations, hiring, and strategy. Harvard Business School MBA."},"Ramin Keene":{"role":"Cofounder","bio":"CTO of StockX and O’Reilly author, with 20 years building and scaling startups.\nL42: I built Rover’s first ML platform, designed streaming data infrastructure at Nordstrom, and led infrastructure for training and serving generative video models at Hedra. My work has always been about making ambitious technology work reliably at scale. Now I’m build"}}},
  "SR007:Nexor AI": {"founded":2026,"overview":"Nexor builds infrastructure for revenue agents. In 5 months since launching, Nexor has grown to 270 clients and grown live revenue from 0 to $2.5M ARR, deploying into enterprise accounts in 19 countries. Companies go live in less than two days, creating agents that chase specific outcomes in their funnels: reactivating churned users, upselling, pushing onboarding and more. Agents on the Nexor Harness are handling over 200k+ daily conversations across voice, iMessage, WhatsApp and email.","founderDetails":{"Gabriel Cid":{"role":"Co-Founder & COO","bio":"Previously, Gabriel founded Capitalizarme.com and scaled it to $2.5B+ in transactions across 25,000+ apartments and 20,000+ investors. He raised $12M+, led two acquisitions, and built a network of 500+ sales partners.\nL41: Now building Nexor AI, backed by a16z Speedrun, which reached $2.5M ARR in five months."},"Ian Lee":{"role":"CEO","bio":"At just 16yrs old, Ian became founding engineer at a YC Company. At 19, he took the Thiel Fellowship and raised $25M from GC, 8VC, and YC to serve over 1M+ patients in LATAM."}}},
  "SR007:Nimble": {"founded":2026,"overview":"US forwarders spend $15B a year on people pushing manual work through email, spreadsheets, and decades-old systems. Nimble's AI agents execute that work for sales and ops teams leveraging company judgement. Recent margin pressures compel forwarders to use AI but there isn't a solution that fits their needs. They lose revenue because they don't have enough headcount to respond to inquiries. Nimble allows them to scale without adding headcount.","founderDetails":{"Aman Kapoor":{"role":"CEO","bio":"Family runs 70 year old forwarding company; previously scaled fintech product from 0 to $5m in rev; supported 30+ PE B2B SaaS CEOs in scaling; managed tech transformation projects for fortune 500s"},"Dhruv Dabriwal":{"role":"CTO","bio":"CTO @ Nimble. Building the AI Operating System for Freight Forwarders. Worked at Azure on building distributed scalable systems following which I worked at Balyasny Asset Management on low latency systems.\nL40: Implementing new ways of RL and fine tuning open weight models and architecting the context and memory layer for Nimble. CS, Econ and Math "}}},
  "SR007:OneGC": {"founded":2025,"overview":"OneGC is the first platform that runs legal for startups. In less than 3 months, the company has scaled to over $1.18M in ARR (420K in pilot), added more than 50 customers, and is growing at 127%+ MoM. OneGC is the first AI-powered platform that runs legal for startups. It turns legal from an outside service that founders have to chase into a product embedded in their business. The platform reviews a company's contracts and records, finds the gaps, autonomously fixes them, and shows founders what to do next. Anything that needs a lawyer's touch goes to OneGC's own law firm of startup attorneys.","founderDetails":{"Evan Vandenberg":{"role":"CEO","bio":"CEO of OneGC, the first platform that runs legal for you. - Previously founder/CEO of Dibbs ($6M+ revenue, $17M raised, acquired 2024) and GM of Voice AI at 11x. More than a decade of building software companies as a product and GTM leader."},"Gabe Azevedo":{"role":"CTO","bio":"Previously founder of Dibbs ($6M+ revenue, $17M raised, acquired 2024).\nL44: 10+ years building software companies as a engineering and product leader."},"Jacques Baritot":{"role":"Co-Founder + General Counsel, OneGC","bio":"General Counsel of OneGC. Previously commercial counsel at Coinbase and Checkr, and an attorney at Fenwick. 13+ years as a transactional lawyer for startups and high-growth tech companies."}}},
  "SR007:Ontem": {"founded":2026,"overview":"Ontem is building the AI-first platform for commercial services businesses to bill, collect, and access financing. Today, finance teams piece together contracts, proof of work, and customer requirements across disconnected systems just to submit a bill, then chase approvals and payment by hand. Ontem connects those systems and runs that work end to end, from billing through collection, improving cash flow. In the process it captures proprietary data on what actually gets invoices paid — data it plans to use to underwrite financing against receivables. Penn classmates Jaime Barrenechea and Jacob Chimerine founded the company; their experience spans Meta, BCG, and Monashees.","founderDetails":{"Jacob Chimerine":{"role":"Co-Founder"},"Jaime Barrenechea":{"role":"Co-founder"}}},
  "SR007:OpenWhispr": {"founded":2026,"overview":"OpenWhispr is an open-source AI notetaker and voice assistant built for even the most privacy-sensitive enterprises. Its on-device models let people dictate and capture meetings without sending sensitive conversations to the cloud. The product has 10,00+ daily active users, growing 30% MoM, and $120K+ in ARR, growing 25% MoM. Paying users include employees at Geotab, Siemens, Vista Equity Partners, Monobank, and Bolt. Founded by Gabe Stein, who has built and exited multiple companies in the past.","founderDetails":{"Gabriel Stein":{"role":"CEO & Founder","bio":"CEO @ OpenWhispr, multiple time exited founder, 7+ years leading product at startups from $0-$150M ARR."}}},
  "SR007:Orbits": {"founded":2026,"overview":"The worst assistant is the one that has to be told what to do and how to do it. Orbits doesn't wait to be asked — it runs your household end-to-end, doing the work proactively: booking the appointment, placing the order, calling the restaurant, sending the text, and registering for camp before space fills up. All while coordinating across all the members of your family, and the ones outside the home that help it run (like the babysitter, or the plumber).","founderDetails":{"Erik Tillberg":{"role":"CTO"},"Nomaan Ahmed":{"role":"Co-founder","bio":"Building Orbits to help busy families save hours every week! - Led product/eng at Super.com, scaling new consumer products from 0 to >$100M ARR and >1M monthly subscribers. - Executive operator, leading product/eng at 2-person startups all the way to Fortune 500 co's"}}},
  "SR007:Oruk": {"founded":2026,"overview":"As AI tools become mainstream and robots enter the workforce, conversation is replacing the text box as the only interface fast enough to keep up with critical demands. The voice layer behind every agent, coding session, robot command, and phone call needs the full context: words, tone of voice, emphasis, intent, and emotion. When someone says \"I'm fine,\" they could be reassuring you or asking you to leave them alone. The words are the same. The meaning is in the voice. We are speech, AI, and linguistics researchers from Stanford, Cambridge, and Berkeley, building Oruk to train speech foundation models that actually understand people.","founderDetails":{"Nathan Roll":{"role":"CEO","bio":"Nathan Roll is co-founder and CEO of Oruk, the first company selected for both a16z Alpha and Speedrun. He paused his Stanford Linguistics PhD to build speech foundation models that understand words, emotion, and delivery. A Stanford EDGE Fellow affiliated with Stanford NLP, Nathan works at the intersection of speech AI, computational neuroscience,"},"Vianney Grenez":{"role":"Co-founder and CTO","bio":"My background sits at the intersection of systems engineering, mechanical and electrical design, and thermal management. I studied at Arts et Métiers and UC Berkeley, then spent four years as an innovation engineer working with Data Center teams at Meta, NVIDIA, and Google. I hold 14 U.S.\nL51: patents—with more to come—and am most energized by turn"}}},
  "SR007:Othello": {"founded":2026,"overview":"Othello builds vertical AI models for B2B sales calls. It post-trains on customer data, then deploys its agents to live customer calls, providing real-time recommendations to sellers. Since May, Othello has scaled to $600k in live ARR, $1.2M in cARR, and $25M in enterprise pipeline. Othello is working with 30 enterprise customers, all of whom have market caps north of $2B. Since launching, Othello has improved conversion rates by over 25%. How? Customers love Othello - we have 95% DAU (compared to Gong's sub-20% DAU) and more enterprise traction than every single predecessor in the category combined. Jared Zelman (CEO) has been building companies since he was 8 years old.","founderDetails":{"Jared Zelman":{"role":"Founder","bio":"- Founder of Othello.ai - Previously founded Cicero.ai - Started my first company in high school, a tutoring business I later sold for ~$900k - Interned at Summit Partners, then worked in private equity - Became the most prolific deal sourcer in Summit Partners history, acc to internal leaderboards - Also a lifelong ketchup sandwich salesman: https"},"Raphael Assor":{"role":"Founder & CTO"}}},
  "SR007:Parca": {"founded":2026,"overview":"Parca is an AI-native pre-construction services firm targeting a $150Bn+ services fee pool. We're backed by top-tier VCs and angels, including a founder of Mercor and operators from Sierra, Tesla, Clay, and Bain. In just seven weeks, we've scaled from $0 to $500k in annualized run-rate revenue and are deployed across 2 out of the top-5 national homebuilders (Toll Brothers and PulteGroup). We draft concept plans, site investigation reports, and feasibility studies for our partners, with every output reviewed by a real estate professional before delivery. Parca is co-founded by Rishab (ex-TPG, Cornell Math), Andy (ex-JPM, Cornell Math + CS), and Ian (ex-Amazon, Cornell CS).","founderDetails":{"Andy Kim":{"role":"CTO","bio":"Ex-JP Morgan Equity Linked & Derivatives. Cornell Math + CS. Built and executed arbitrage strategies in crypto."},"Rishab Yeddula":{"role":"CEO","bio":"Ex-TPG Real Estate, Morgan Stanley. Cornell Math + Economics. Closed & advised on $10Bn+ of real estate transactions including Tricon Residential's sale to Blackstone, TPG's acquisition of ECHO Realty, and Blue Owl's acquisition of IPI Data Centers."}}},
  "SR007:PhotonSpear": {"founded":2026,"overview":"PhotonSpear builds laser weapons that destroy ballistic missiles in boost phase. Its adaptive optics keep the beam concentrated and lethal at space-relevant ranges. CEO Wes Foudriat flew F-16s for a decade and led technical analysis of space-based interceptors in the Space Force. CTO Dr. Connor Beierle holds a Stanford PhD in astronautics and is a distinguished graduate of the Air Force Test Pilot School. He has spent more than 14 years at NVIDIA, Google, and Blue Origin, where he led flight test for the Artemis lunar lander.","founderDetails":{"Wesley Foudriat":{"role":"CEO","bio":"Prior fighter pilot and technical analyst for Golden Dome's space-based interceptors. Deep expertise in the Department of War's hardest problem set. Now building the orbital lasers to solve it."}}},
  "SR007:Phyvant": {"founded":2025,"overview":"AI can now solve problems experts spent decades on. Yet most companies still use it one task at a time: a person breaks down every goal, supplies every piece of context, and checks every result. The models keep getting better, but the business still moves at the speed of the people managing them. Phyvant works the other way. Give us a business number and the lines we can't cross. We deploy a fleet of agents that works every case in parallel, applying your experts' judgment around the clock until the target is met. We built Phyvant alongside America's largest private company on their M&A process. A key bottleneck that took their team three weeks per deal now runs fully autonomously.","founderDetails":{"Khedaar Kashyap":{"role":"CTO","bio":"Ex-NASA, California Observatories, The Hoover Institution"},"Nihal Gunukula":{"role":"CEO","bio":"Ex - MLE @ Mercor, Army funded RL Research"}}},
  "SR007:PreMan": {"founded":2026,"overview":"PreMan is a self-healing QA platform for the agentic era. Built for fast-shipping software teams, it discovers existing tests, maps the end-to-end workflows they cover, and generates adjacent scenarios for QA leads at fast-shipping software companies. Unlike manually maintained test suites, Preman’s coverage adapts as products and workflows change. Developers can run and expand tests from the desktop app or terminal using plain English. Customer adoption has already brought Preman to $170K ARR.","founderDetails":{"Alspencer Omondi":{"role":"CEO","bio":"Ex-founding engineer at Surt AI ($0-1M ARR in 6 months); Won the Citadel poker tournament; 99.99 Percentile rated chess player."},"Korin Aldam-Tajima":{"role":"CTO","bio":"Published Theoretical physics researcher who dropped out of grad school to start  Preman; national-level finalist swimmer; self-taught C++ and computer graphics in high school to recreate Minecraft."}}},
  "SR007:Primitive Labs": {"founded":2026,"overview":"Primitive Labs is building the behavioral intelligence layer for AI, modeling human behavior so companies can predict how people will respond to software and agents before they launch. Our proprietary behavioral modeling technology powers agents that simulate real human decision-making, laying the foundation for our ambition to become the behavioral validation layer for every piece of software. Our team comes from Amazon Artificial General Intelligence, Amazon Science, AWS, Google, Harvard, and MIT. We launched generative AI infrastructure and models at Amazon and built multiple products from $0 to $1B+.","founderDetails":{"Gabriel Fong":{"role":"Co-Founder & COO","bio":"Prev. AWS and DoiT, Northeastern Alum"},"Jean Farmer":{"role":"Co-Founder & CTO","bio":"Prev. Amazon Artificial General Intelligence (AGI) building agentic capabilities into Amazon's proprietary LLMs. Colorado School of Mines Alum."},"Rohit Talluri":{"role":"Co-Founder & CEO","bio":"Prev. Amazon Artificial General Intelligence (AGI) Autonomy Lab, AWS Foundation Model Training & Inference Team, University of Washington."}}},
  "SR007:Proper Motion": {"founded":2025,"overview":"Proper Motion is building continual learning infrastructure for every AI agent. We help teams deploy agents that become more effective, reliable, and capable by turning real-world interactions into lessons they can learn. Our founders are Rafit, Advitya, and Adrian. Rafit (ex-OpenAI) co-created self-healing agents for 1B ChatGPT users, Advitya (ex-Citadel Securities) owned US equities market data to drive 8 figures in PnL and Adrian (Harvard Law dropout) operated on NA’s largest infrastructure projects. In 3 weeks, we’ve scaled our private-beta to $270k+ ARR and have active pilots with vertical AI leaders in finance, legal and healthcare.","founderDetails":{"Adrian Aliu":{"role":"Co-founder","bio":"I'm Adrian, COO at Proper Motion.\nL43: I studied urban planning at Waterloo, worked in Canada and the UK, and deferred Harvard Law to build with friends."},"Advitya Chhabra":{"role":"CEO","bio":"Owned US equity market data and led initiatives to unlock eight figures of PnL at Citadel Securities, studied software engineering @ UWaterloo."},"Rafit Jamil":{"role":"Co-founder","bio":"At OpenAI I founded the User Reward Model team and pioneered early forms of self-healing agents and continual learning for ChatGPT."}}},
  "SR007:Reelful": {"founded":2025,"overview":"Reelful is a personal video-editing agent that turns raw footage into ready-to-post content shaped by user’s taste and intent. Creators, small business owners, and founders have a pressing need to create and post content regularly but most don't have the time or expertise. Reelful's direct-to-consumer product enables agents to own content end-to-end, cutting editing time by 90%. Founded by Kate Deyneka, ex-Snapchat senior ML engineer who led video generation to production for millions of users and creators.","founderDetails":{"Kate Deyneka":{"role":"Founder & CEO","bio":"ex-Snapchat senior ML engineer who led video generation to production for millions of users and creators"}}},
  "SR007:Rhema Health": {"founded":2026,"overview":"Rhema Health powers preventive care delivery for Medicare. Our AI agents automate patient care from outreach to billable outcomes. Starting with specialists in podiatry, endocrinology, and cardiology, whose critical workflows demand deep, multi-touch integration. An a16z Speedrun company, we're at $500K cARR, live on athenahealth's marketplace with access to 10K providers, and have a $3M+ pipeline. Medicare is shifting to reward engagement and outcomes over coding intensity. Engagement at scale is a consumer conversion problem hiding inside healthtech. Dave and Adam spent 10 years solving it at Meta, including scaling Reels Monetization 0 to $10B and building AI personalization for newsfeed.","founderDetails":{"Adam Davison":{"role":"Co-Founder","bio":"Adam was an early employee at LiveRail, which Facebook acquired in 2014. He went on to spend a decade at Meta, most recently leading Reels Monetization from $0 to over $10B. He knows how to get millions of people to engage with a product.\nL43: Now he's co-founding Rhema to bring that expertise to healthcare, helping medical groups engage their pati"},"Dave Moore":{"role":"CEO & Co-Founder","bio":"I'm the Co-Founder and CEO of Rhema Health. Rhema powers preventative care delivery for Medicare specialties. We deliver clinical use cases end to end, from outreach through billable outcomes. This work is personal. In 2024-25 I navigated a serious chronic condition myself, and my wife led Annual Wellness at Palo Alto Medical Foundation.\nL41: Livin"}}},
  "SR007:Ripline": {"founded":2026,"overview":"Ripline is an applied research lab deploying sovereign intelligence in critical industries. Our wedge is deploying agents to do operational tasks like orchestrating complex supply chains, navigating compliance hurdles, and financial modeling. Historically, physical change has been slow and long-winded. That changes with Ripline.","founderDetails":{"Anwith Telluri":{"role":"Co-founder","bio":"ex-Profound, SpaceX, Cal AI, Scale AI; UIUC grad"},"Hriday Unadkat":{"role":"Co-Founder","bio":"Ex-Reflect Orbital, SpaceX, NASA; Princeton grad"}}},
  "SR007:Rollup": {"founded":2026,"overview":"Rollup gives any app years of user context, in minutes. We help personal AI assistants and consumer apps understand users’ interests, preferences, and experiences from day one. Our SDK uses on-device AI to turn camera rolls into structured context for personalization, without photos leaving the phone. Long-term, Rollup becomes a universal context layer for every app. We signed 8 customers representing $288K in cARR in 14 days and are doubling our revenue WoW. We have 10M+ MAUs in our qualified pipeline, including the 1) largest traditional retailer by revenue in the world and 2) the second-largest supermarket operator in North America.","founderDetails":{"J Yim":{"role":"Co-Founder / CEO","bio":"Stanford B.S. CS (AI/ML) + Acting & M.S. MS&E. Previously founded a venture-backed software company that raised $5M+. Grew up between Seoul, New York, and Los Angeles in a family spanning generations of fashion, photography, media, and visual culture."},"Nora Xiao":{"role":"Co-Founder / CTO","bio":"Caltech CS. AI engineering at Databricks, Notion, Amazon. AI research (16 y/o) at Harvard, Princeton, EPFL."}}},
  "SR007:Rumbo": {"founded":2026,"overview":"Rumbo is building the AI infrastructure for global trade, starting with freight forwarders on U.S.–Latin America trade lanes. Our agents turn messy emails, PDFs, and screenshots into shipment quotes in minutes instead of hours, with operators making the final call. We’re expanding beyond quoting to automate work across freight operations. Our goal: help forwarders move ten times the cargo with the teams they already have.","founderDetails":{"Agustin Baiocco":{"role":"CTO","bio":"Co-founder and CPTO at Rumbo, where I lead product and engineering.\nL42: Rumbo is building the agent layer for global trade, starting with freight forwarders on US-LATAM lanes: agents that read real quote requests, price them in minutes, and hand everything to an operator for the final call. Before Rumbo I spent years in product, most recently lead"},"Gonzalo Leiva":{"role":"Co-Founder & Head of Sales","bio":"Co-founder and Head of Sales at Rumbo, where I lead go-to-market and work directly with the forwarders we build for.\nL43: Before Rumbo I spent twelve years in freight forwarding, from early-career roles to leading the commercial team at one of the top 5 global forwarders in Argentina. I've managed, sold and operated the same shipments our agents no"},"Guido Haissiner":{"role":"CEO","bio":"Co-founder and CEO at Rumbo. I’m a Stanford MBA and second-time founder, having previously built and sold a high frequency trading algorithm. (Schermo Capital). Before Rumbo, I spent three years in corporate finance at Rappi and two years in cybersecurity at Mastercard."}}},
  "SR007:Saru": {"founded":2026,"overview":"Saru is building the customer-facing agent layer for consumer brands. Brands have millions of customers, but almost no individual relationships with them. Saru gives brands AI agents that use brand voice to build personalized 1-to-1 relationships with every customer across the entire user journey, natively on iMessage, Instagram, and other conversational surfaces. The agents use purchase history, social engagement, and conversational memory to know when to take action, whether that’s to recommend, sell, solve a problem, re-engage, or simply entertain. Every conversation captures why customers buy and what matters to them, deepening the relationship and driving higher lifetime value.","founderDetails":{"Amar Lathia":{"role":"Co-Founder & CEO","bio":"MBA from Harvard Business School; 7+ years in consumer / commerce investing experience across PE (H.I.G. Capital) and Investment Banking (J.P. Morgan)"},"Tarun Khasnavis":{"role":"Co-founder and CTO","bio":"Hi I'm Tarun! I've been a product engineer for the past 7 years. I worked at Salesforce building core product features and an early engineer at a 1B+ startup."}}},
  "SR007:scaledrive.ai": {"founded":2024,"overview":"At scaledrive, we build safe Physical AI that unlocks the full potential of autonomous industrial robots in human environments. Our software is backed by TÜV, the world’s leading certification agency, and runs across robot types, delivering up to 45% higher productivity and up to 4x faster learning. We have paid, real-world pilots in ports and with the world’s fourth-largest shipbuilder, and are expanding into airports, automotive, and data centers. Our team brings together Stanford robotics researchers and autonomy leaders who have deployed robots at scale, backed by the former head of Google Robotics (now a distinguished engineer at Waymo) and Niantic's founder.","founderDetails":{"Denis Azarov":{"role":"CEO","bio":"I'm co-founder and CEO of scaledrive.ai. Previously, I built models of human behavior for leading autonomous driving companies at another startup, developed patented software, and managed large innovation programs at BMW. Engg Master @ TU Vienna & MBA @ TU Munich. Visiting student @ UC Berkeley. Visiting speaker @ UC Berkeley Haas & Stanford contin"},"Jakob Thumm":{"role":"CTO","bio":"I'm the CTO of scaledrive.ai, where we develop provably safe physical AI for industrial robots. Prior to founding scaledrive.ai, I was a postdoctoral scholar at Stanford University in the Autonomous Systems Lab under supervision of Marco Pavone. I earned my Ph.D.\nL50: in Computer Engineering from the Technical University of Munich with highest dist"}}},
  "SR007:SenseLab": {"founded":2026,"overview":"SenseLab builds recursive learning infrastructure for AI agents and models. It connects agent decisions to outcomes, helps teams identify and test improvements, and turns successful runs into training data for smaller, specialized models. Founded by Bruno and Dai, who previously built companies acquired by Juniper Networks and Mirantis.","founderDetails":{"Bruno Andrade":{"role":"CEO - Founder","bio":"Co-founder of SenseLab, the cognitive infrastructure for agent fleets. Third infrastructure startup with the same co-founder — last two got acquired. Built and scaled OLAP (and in-memory) databases and distributed infrastructure before going full-time as a founder. Lover of pizza, sushi, and cooking."},"Dai Macedo":{"role":"Co-founder SenseLab","bio":"I’ve spent the past decade building and scaling infrastructure products, focused on product strategy and go-to-market.\nL42: Two exits to Juniper Networks and Mirantis."}}},
  "SR007:Sonder": {"founded":2026,"overview":"Sonder is an AI lab building on-device vision models that watch people’s screens, learn how they work, and act before they think to ask. Its models turn the context and workflows they observe into shareable skills that teammates’ agents can use. Sonder is built for enterprises that want to own their intelligence and data. The team is post-training small vision-language models and has already achieved 3× faster inference at half the size of the baseline on consumer-grade laptops. They built a desktop RL environment to train these models, keeping it in-house despite outside licensing interest.","founderDetails":{"Ajit Krishna":{"role":"CTO","bio":"Microsoft Imagine Cup World Champion and Software Engineer who’s led deployments for healthcare’s biggest players, including Aetna, Blue Shield, and Oscar Health.\nL41: Previously on the founding engineering team at Anterior (Sequoia and NEA backed) and was a senior engineer at Clarion (YC and Accel backed)."},"Riyan Moussaoui":{"role":"CEO","bio":"Medical Doctor turned AI engineer. Previously Co-Founder/CEO of FutureClinic (YC Backed, $5M raised) and AI Engineer at Anterior (Sequoia and NEA backed). I’ve been training language models since GPT-1, putting them to work for clinicians, patients, pharma teams, and scientists."}}},
  "SR007:Sotant": {"founded":2026,"overview":"Sotant creates agentic systems for complex supply chain operations. We are already live with leading global enterprises such as DHL and Bimbo – providing them with teams of autonomous AI employees that deliver end-to-end business outcomes that would have taken months of human labor. Our proprietary technology replicates how experts work and make decisions, creates custom AI employees in just hours, and automates entire organizations.","founderDetails":{"Eduardo Candela":{"role":"CEO","bio":"I'm the CEO and Co-Founder of Sotant, an AI startup that provides custom and reliable AI employees for complex operations, in just hours. I hold a PhD in AI for Autonomous Vehicles from Imperial College London, and Master’s in Operations Research from MIT. I previously co-founded Maihem (YC W24), and worked in Silicon Valley developing and deployin"},"Juan-David Rodriguez":{"role":"COO","bio":"Growth hacker at heart.\nL46: Now building growth and distribution at Sotant, where we build agentic AI workforces for supply chain companies to scale operations without adding headcount. Previously, I founded Teilur, Inc, where I used growth hacking, performance marketing, and lean go-to-market systems to bootstrap and scale multiple business units"}}},
  "SR007:Space": {"founded":2026,"overview":"Space is building the AI-native filesystem. It gives every agent instant access to petabytes of shared context, streaming only the bytes it needs. SpaceFS works across any computer, without syncing files or using local disk space. Because Space works at the filesystem level, agents and people can share context across tools and interfaces, with no per-app integrations. It’s already 2–50× faster than other high-performance virtual filesystems on real-world workloads. The team’s second-time founders bootstrapped their previous startup Eden.so to $1M+ ARR in under ten months.","founderDetails":{"Ari Bapna":{"role":"Co-Founder, CTO"},"Jason Zhao":{"role":"Cofounder & COO"},"Matthew Ao":{"role":"Cofounder & CEO","bio":"Previously bootstrapped eden.so to $1M+ ARR in under 10 months. Dropped out of UofT Engineering. Matt & Ari on YouTube (23k subs)."}}},
  "SR007:Spun Labs": {"founded":2025,"overview":"Creators earn $130B+ annually across royalties and other variable income streams, yet turning fragmented, delayed income into usable capital has always meant predatory advances and giving up future earnings—until now. Spun Labs is building the Creator Card: a free, creator-specific credit card that uses proprietary AI to intelligently underwrite these income streams and solve payment lags—offering real-time access to earnings, data-driven credit limits, dynamic repayment periods, and hyper-specific rewards for creators. Spun monetizes through merchant interchange, letting creators keep 100% of earnings and ownership.","founderDetails":{"Aaron Zhang":{"role":"Co-Founder","bio":"Most recently at Google Labs (6 yrs), previously at FB, Lyft, Microsoft, Brown CS"},"Andrew Zhang":{"role":"Co-Founder","bio":"stanford cs + symsys, graduated top 10% of class ex-apple ai research ex-stanford ai research + audio/acoustics research (published) ranked #2 jazz trombonist in the USA at 17 years old co-founded the band six of spades with my best friends in college and went viral"},"Kai Charp":{"role":"Co-Founder and CEO","bio":"Plays 6 instruments, youngest SF Marathon finisher at 10 years old, Stanford Econ graduate, fintech researcher, founded viral college band, founded indie record label. I want to live in a world where creatives are shown how much they are valued, and where they are given the financial freedom to create. I want to live in a world that champions perfo"}}},
  "SR007:Sterling": {"founded":2026,"overview":"Sterling builds long horizon agents that own business outcomes: managing renewals, dynamically allocating ad spend across channels, coordinating across product and engineering to ship deal-blocking features, and more. Our agent harness is built for long-horizon work: it constructs an ontology from each company’s data and gives agents memory, company-specific evals, and guardrails on every action. In one month, they’ve completed 4 company-level deployments. The first two of them converted to $150k ARR in annual contracts, with $300k additional ARR converting in 2 weeks across live deployments. Backed by early investors and operators at Pinterest, Stripe, Mercor, OpenAI, and Instinct.","founderDetails":{"Amit Kallakuri":{"role":"COO","bio":"Ex-Clay, a16z enterprise + fintech | Dartmouth College"},"Bradley Xu":{"role":"CTO","bio":"Ex-Reve (acq. Frontier AI Lab), Sutter Hill Ventures, Sigma, Amazon | Math and CS @ Carnegie Mellon"},"Spandan Das":{"role":"CEO","bio":"Ex-DatologyAI, NVIDIA, Apple, NASA | published NeurIPS researcher | CS @ Carnegie Mellon"}}},
  "SR007:Superintelligence Foundry": {"founded":2026,"overview":"We are building a creative AGI: a scientist, engineer, and entrepreneur that learns by acting in the world, keeps improving, and is intrinsically motivated to make the world better. Our breakthroughs include intrinsic alignment that scales, open-ended self-improvement, and connecting AGI into the physical world. Our business model is to turn capital into invention, discovery, and the creation of autonomous companies. Our core algorithmic unlocks: 1. Intrinsic Alignment: [ first announcement https://superfoundry.dev/resources/align ] 2. Self-Directed Learning [ to be announced soon ] 3. Physical Agency [ to be announced soon ]","founderDetails":{"Jad Tarifi":{"role":"CEO"},"Nima Asgharbeygi":{"role":"CTO"}}},
  "SR007:Switchfrog": {"founded":2026,"overview":"Switchfrog lets companies identify, govern, and monetize AI agents navigating with user accounts. We detect the exact moment a human hands off control to an agent, enforce compliance and access rules, and automatically compile multi-step web workflows into agent-native tools. User-directed AI requests have surged 37x since the beginning of last year, and doubled in the past month. Over $15 trillion in B2B spending is forecast to flow through AI agents by 2028, and AI agents are expected to mediate $3–5 trillion in consumer commerce by 2030. Switchfrog enables businesses to see AI agent usage, then turn their products into apps for agents.","founderDetails":{"Tommy McCormick":{"role":"CEO","bio":"Tommy started working on security and cryptography at Microsoft when he was 16, then built social commerce software that brands like Nike and Target embedded on their websites to drive growth. He was leading the data infrastructure team at Faire when ChatGPT launched and saw firsthand how internet commerce would shift again.\nL39: Switchfrog is the "}}},
  "SR007:Tenera": {"founded":2026,"overview":"Tenera trains frontier simulation models that predict how users react to software before it ships, bringing an AI judgment layer to the product development lifecycle. “What should we build next?” has become the most critical question in software. Enter Tenera: simulation AI that validates every decision before it’s made. Our simulation models predict how users will react - and impact on business metrics - with 85% accuracy before anything ships. Research and experimentation cycles that took 3 months now take 1-2 days.","founderDetails":{"Nicole Orsak":{"role":"Co-founder & CEO","bio":"Prev. led product @ Uber Eats (drove $1B+ revenue and Uber's highest-performing experiment) · Ex-Twitter, Disney+ PM · Stanford MS&E alum"},"Yuqi Li":{"role":"Co-Founder & CTO","bio":"Prev. built simulated users @ NVIDIA and Doctronic (founding AI engineer, helped close eight-figure deals) · Published RL researcher · Waterloo ECE, Carnegie Mellon MS"}}},
  "SR007:Truli": {"founded":2025,"overview":"Truli is building AI-native regulatory compliance for consumer products, starting with food, beverage, and supplements. The platform automates regulatory review across the product lifecycle, from product development and packaging to post-launch marketing and social media, while continuously monitoring regulatory changes, enforcement, and litigation. The founders started Truli after navigating compliance challenges firsthand while launching their own supplement.","founderDetails":{"Catherine Zhou":{"role":"Co-founder, CEO","bio":"Built ML models and discovered two novel drugs at Stanford Med + MD Anderson, published in Nature at 18 y/o, youngest presenter at ISMB/intl’ bioinformatics conferences; studied CS + Biochemistry @ Rice"},"Michael Wu":{"role":"Cofounder, COO","bio":"Deployed AI at financial institutions and built compliance automation @ Clausey (AI Compliance Startup), national debate champion, 2x international piano champion, 1M+ views on socials; CS @ Rice."}}},
  "SR007:Valent": {"founded":2026,"overview":"Valent is building the agentic platform that will turn Western manufacturers into the next generation of industrial leaders. Starting with the defense industrial base, Valent provides the ground truth evidence layer that helps manufacturers win contracts, enter new markets, and ramp production, laying the foundation for an industry of AI-native factories. In just 6 weeks they scaled to $180k annualized revenue, built a pipeline of $5M across industrial segments that are notoriously hard to penetrate, and hired an ex-Meta engineer to support expansion. CEO Felix Zerbib is an industrial engineer who rebuilt supply chain ops for some of the worlds largest critical minerals companies.","founderDetails":{"Beni Shafer-Sull":{"role":"Co-founder","bio":"Led research and engineering as the head quant for all Bridgewater Asia strategies (>$20B AUM) and Bridgewater's China fund (largest hedge fund in China).\nL42: Former founder at a VC-backed (Speedrun, Village Global, Motivate, Four Cities) agentic data engineering company that processed billions of rows of enterprise data. Ex-BlackRock Wharton and "},"Felix Zerbib":{"role":"co-founder","bio":"Felix is a chemical engineer who spent 7 years rebuilding supply chain for the largest critical minerals companies, and ran operations at a prior startup that raised $40m"}}},
  "SR007:Vela Energy": {"founded":2026,"overview":"Vela is building the AI workforce for power delivery. Its live project model connects utility studies, electrical designs, equipment records, and schedules, enabling agents to evaluate power configurations, source compatible equipment, prepare interconnection submissions, and trace changes across engineering, procurement, cost, and schedule. Developers and EPCs can see what capacity can be energized, when, and what must happen to get there. CEO Tarun Batchu is a patented environmental engineer who began building energy technologies at 12 and withdrew from Berkeley MET to build Vela.","founderDetails":{"Tarun Batchu":{"role":"Co-Founder & CEO"},"Tony Li":{"role":"Co-Founder & COO"}}},
  "SR007:Vene Health": {"founded":2026,"overview":"Ex-Apple, xAI, leading ML researchers, and experience scaling health platforms. Vene gives families an AI patient advocate over text. It uses specialized calling and browser agents to act on their behalf, with an agent-native EHR providing the health context to handle everything from appointments and refills to insurance and ongoing follow-up.","founderDetails":{"Aritra Saha":{"role":"Co-Founder and COO","bio":"Georgia Tech grad in two years. Led Groq Core Product at xAI; did ML at Apple, turned down an MIT PhD.\nL46: Managed my grandfather's cancer care for a year."},"Nik Nandi":{"role":"Co-Founder & CTO","bio":"Georgia Tech, CS + Applied Math, ML researcher with research at KDD, NeurIPS, and built top Hugging Face datasets. Cared for my grandmother before and into hospice."},"Sujal Dhakal":{"role":"Co-Founder & CEO","bio":"Georgia Tech dropout. Scaled a platform delivering $50M/year in medical supplies; youngest engineer hired at Phia. Managed my parents’ chronic conditions at 17."}}},
  "SR007:Vound": {"founded":2026,"overview":"Robots learn by watching people work. But the footage they need, real people doing real jobs in real workplaces, barely exists, and it can't be scraped or simulated. Vound supplies it at scale from hard-to-access commercial environments: first-person video of skilled work in factories, farms, hotels, construction sites and dozens of other settings, captured across industries and geographies that others can't reach, and delivered with the task labels and quality control that robotics labs need to train general-purpose models. That access is the foundation of a bigger plan.","founderDetails":{"Adham Bedir":{"role":"Co-founder & CEO","bio":"I'm Adham, co-founder and CEO of Vound. I grew up in Egypt, studied at Harvard College and Harvard Business School, and spent my career before Vound in finance: M&A at JPMorgan in New York, then Africa-focused private equity at DPI in London, working on more than $50bn of deals across 30+ industries and four continents. I'm based in Palo Alto and s"},"Aly M. Siessa":{"role":"Co-founder"},"Youssif Siessa":{"role":"CTO"}}},
  "SR007:Zoah": {"founded":2025,"overview":"Zoah is the next evolution in software development. It’s where teams can collaboratively design, build, and deploy stable software at scale, completely visually. Eliminating the gap between design and engineering, once and for all. Founder Drew Wilson is a repeat and exited former YC founder, and has assembled a dream team of builders from Adobe, Github, Microsoft, and Slack to bring exceptional design to every product. And to be the platform where the next era of software gets created.","founderDetails":{"Drew Wilson":{"role":"Founder & CEO","bio":"I’m a repeat and exited former YC founder. I've been working as both a designer and engineer for the last 30 years."}}},
  "SR007:Zorbe": {"founded":2026,"overview":"Zorbe is building the owned intelligence layer for every company. We turn repetitive production workloads across text, vision, speech, image, and video into specialized foundation models that companies can own and continuously improve. Using distillation, fine-tuning, reinforcement learning, and architecture optimization, Zorbe converts general-purpose intelligence into models built around how each business actually operates. As a company’s data, usage, and the frontier evolve, its intelligence evolves with it. Over time, Zorbe becomes the system that builds, operates, and compounds the proprietary intelligence running the business.","founderDetails":{"Pranay Sadani":{"role":"Co-Founder"},"Yash Iyer":{"role":"Co-Founder"}}},
};
